const normalizeExerciseName = (name: string) => name.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()

export const exerciseTechniqueRuByName: Record<string, string> = {
  [normalizeExerciseName('Dumbbell Pullover')]:
    '1. Подготовка\nЛягте поперек горизонтальной скамьи так, чтобы верхняя часть спины была на опоре. Держите одну гантель двумя руками над грудью, руки слегка согнуты в локтях.\n2. Исходное положение\nПлотно поставьте стопы на пол и держите таз немного ниже уровня скамьи для хорошего растяжения.\n3. Фаза опускания\nМедленно опускайте гантель за голову по дуге, сохраняя небольшой сгиб в локтях. Остановитесь, когда почувствуете глубокое растяжение широчайших мышц спины и грудных мышц.\n4. Фаза подтягивания\nВерните гантель в исходное положение над грудью, ведя движение за счет широчайших мышц спины.\n5. Дыхание\nВдыхайте, когда опускаете вес за голову, и выдыхайте, когда возвращаете его над грудью.\n\nКлючевые моменты:\n- Сохраняйте небольшой сгиб в локтях на всем протяжении движения: не выпрямляйте и не сгибайте их сильнее во время повторения.\n- Опускайте таз немного ниже уровня скамьи, чтобы увеличить растяжение.\n- Фокусируйтесь на сокращении широчайших, а не на выжиме грудью.',

  [normalizeExerciseName('Barbell Pullover')]:
    '1. Подготовка\nЛягте на скамью, расположив голову ближе к краю. Возьмите штангу узким хватом сверху, руки выпрямлены над грудью.\n2. Исходное положение\nСтопы на полу, корпус напряжен, в локтях небольшой сгиб.\n3. Фаза опускания\nОпускайте штангу за голову по контролируемой дуге, пока не почувствуете выраженное растяжение широчайших и грудных мышц.\n4. Фаза подтягивания\nВерните штангу над грудью за счет широчайших, сохраняя угол в локтях неизменным на всем протяжении движения.\n5. Завершение\nВернитесь в исходное положение и сожмите широчайшие перед следующим повторением.\n\nКлючевые моменты:\n- При опускании штанги не сгибайте локти сильнее: угол в локтях должен оставаться фиксированным.\n- Не допускайте чрезмерного отрыва поясницы от скамьи.\n- Используйте умеренный вес, чтобы сохранять контроль во всей амплитуде движения.',

  [normalizeExerciseName('Arnold Press')]:
    '1. Подготовка\nСядьте на скамью с опорой для спины. Держите гантели на уровне плеч, ладони развернуты к вам (как в верхней точке подъема на бицепс).\n2. Исходное положение\nГантели перед лицом, локти перед корпусом, ладони смотрят на вас.\n3. Жим с разворотом\nЖмите вверх и одновременно разворачивайте ладони наружу. На середине траектории ладони должны смотреть в стороны.\n4. Верхняя позиция\nПолностью выпрямите руки над головой, ладони теперь направлены вперед. Коротко зафиксируйте сокращение вверху.\n5. Опускание с обратным разворотом\nВыполните движение в обратном порядке: опускайте гантели и одновременно разворачивайте ладони обратно к лицу.\n\nКлючевые моменты:\n- Разворот добавляет нагрузку на среднюю дельтовидную мышцу, которой не хватает в обычном жиме.\n- Разворачивайте кисти плавно во время всего жима, а не отдельно до или после него.\n- Используйте меньший вес, чем в обычном жиме на плечи, из-за вращательного компонента.',

  [normalizeExerciseName('Arnold Press (Home Version)')]:
    'Техника выполнения\n1. Позиция\nСядьте или встаньте, удерживая отягощение на уровне плеч. Ладони направлены к себе.\n\n2. Исходное положение\nОтягощение перед лицом, локти выведены вперёд, ладони смотрят на вас.\n\n3. Движение\nВыжимайте отягощение вверх, одновременно разворачивая ладони наружу. В середине движения ладони направлены в стороны.\n\n4. Верхняя точка\nПолностью выпрямите руки, ладони направлены вперёд. Сожмите плечи.\n\n5. Возврат\nМедленно опускайте отягощение вниз, одновременно разворачивая ладони обратно к себе.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nВращение усиливает нагрузку на средние пучки дельтовидных мышц\nДвижение и разворот выполняются одновременно, без пауз\nИспользуйте меньший вес, чем в классическом жиме, для сохранения контроля 💪',

  [normalizeExerciseName('Machine Shoulder Press')]:
    '1. Подготовка\nОтрегулируйте сиденье так, чтобы рукояти были на уровне плеч. Сядьте и плотно прижмитесь спиной к спинке.\n2. Исходное положение\nВозьмитесь за рукояти хватом ладонями вперед, локти согнуты примерно под 90 градусов.\n3. Жим\nВыжмите рукояти вверх до полного выпрямления рук, не отрывая спину от спинки.\n4. Верхняя позиция\nВ точке полного разгибания зафиксируйтесь на 1 секунду и сожмите мышцы плеч.\n5. Опускание\nМедленно опустите рукояти обратно до уровня плеч, контролируя вес.\n\nКлючевые моменты:\n- Тренажер задает траекторию, поэтому упражнение безопасно для больших весов и удобно для новичков.\n- На всем подходе держите спину прижатой к спинке: не прогибайтесь и не отрывайтесь от нее.\n- Настройте высоту сиденья так, чтобы локти в старте были примерно под 90 градусов.',

  [normalizeExerciseName('Lean-Away Lateral Raise')]:
    '1. Подготовка\nВозьмитесь одной рукой за устойчивую опору (стойка, столб, рама). Во второй руке держите гантель у бедра.\n2. Исходное положение\nОтклоните корпус от опоры, создав угол. Это увеличивает амплитуду движения в нижней части подъема.\n3. Подъем\nПоднимайте гантель в сторону до уровня плеча.\n4. Верхняя позиция\nКороткая пауза вверху. Почувствуйте полное сокращение средней дельтовидной мышцы.\n5. Опускание\nМедленно опустите гантель в исходное положение, сохраняя одинаковый угол наклона корпуса.\n\nКлючевые моменты:\n- Наклон увеличивает рабочую амплитуду, поэтому напряжение в средней дельте сохраняется даже внизу.\n- Этот вариант сложнее стандартных подъемов в стороны, поэтому используйте меньший вес.\n- Угол наклона должен оставаться постоянным: не выпрямляйтесь во время подъема.',

  [normalizeExerciseName('Incline Chest Press Machine')]:
    '1. Подготовка\nОтрегулируйте сиденье тренажера для наклонного жима так, чтобы рукояти были на уровне верхней части груди. Сядьте, прижав спину к спинке.\n2. Исходное положение\nВозьмитесь за рукояти, сведите лопатки, поставьте стопы на пол.\n3. Жим\nВыжмите рукояти вперед и немного вверх до почти полного выпрямления рук.\n4. Верхняя позиция\nВ верхней точке сожмите верх грудных мышц и удерживайте 1 секунду.\n5. Возврат\nМедленно верните рукояти в исходное положение под контролем.\n\nКлючевые моменты:\n- Наклонная траектория нагружает верхние пучки грудных мышц так же, как и наклонный жим со свободным весом.\n- Тренажер стабилизирует траекторию, поэтому можно максимально сосредоточиться на самом жиме.\n- Отлично подходит как добивающее упражнение после жимов со свободными весами.',

  [normalizeExerciseName('Incline Push-Ups')]:
    'Техника выполнения\n1. Позиция\nПоставьте ладони на возвышение (скамья, платформа или устойчивый стул) чуть шире плеч.\n\n2. Исходное положение\nВытяните ноги назад, тело образует прямую линию от головы до пят. Руки полностью выпрямлены, корпус стабилен.\n\n3. Движение\nСгибайте руки в локтях, опуская грудную клетку к опоре. Локти направлены под углом около 45°.\n\n4. Нижняя точка\nОпуститесь до положения, при котором грудная клетка почти касается опоры.\n\n5. Возврат\nОттолкнитесь ладонями и вернитесь в исходное положение, полностью выпрямляя руки.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nЧем выше опора, тем легче упражнение — хороший вариант для перехода к отжиманиям от пола\nСохраняйте жёсткую линию тела, избегайте провисания или подъёма таза\nЭтот вариант снижает нагрузку на грудные мышцы и трицепсы по сравнению с классическими отжиманиями 💪',

  [normalizeExerciseName('Decline Push-Ups')]:
    'Техника выполнения\n1. Позиция\nПоставьте стопы на возвышение (скамья, платформа, степ), руки на полу чуть шире плеч.\n\n2. Исходное положение\nТело образует прямую или слегка наклонную линию от головы до пят. Руки полностью выпрямлены, корпус стабилен.\n\n3. Движение\nСгибайте руки в локтях, опуская грудную клетку к полу. Локти направлены под углом около 45°.\n\n4. Нижняя точка\nОпуститесь до положения, при котором грудная клетка почти касается пола.\n\n5. Возврат\nОттолкнитесь ладонями и вернитесь в исходное положение, полностью выпрямляя руки.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nЧем выше опора для ног, тем больше нагрузка смещается на верхнюю часть грудных мышц и плечи\nСохраняйте стабильность корпуса — не допускайте провисания таза\nЭтот вариант увеличивает нагрузку по сравнению с классическими отжиманиями 💪',

  [normalizeExerciseName('Knee Push-Ups')]:
    'Техника выполнения\n1. Позиция\nПоставьте ладони на пол чуть шире плеч. Вытяните ноги назад, тело образует прямую линию от головы до пят.\n\n2. Исходное положение\nРуки полностью выпрямлены, корпус стабилен, ягодицы напряжены. Плечи находятся над запястьями.\n\n3. Движение\nСгибайте руки в локтях, опуская грудную клетку к полу. Локти направлены под углом около 45° к корпусу.\n\n4. Нижняя точка\nОпуститесь до положения, при котором грудная клетка находится близко к полу или слегка касается его. Сохраняйте прямую линию тела.\n\n5. Возврат\nОттолкнитесь ладонями и вернитесь в исходное положение, полностью выпрямляя руки.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nСохраняйте стабильность корпуса — не допускайте провисания таза\nЛокти под углом около 45° помогают снизить нагрузку на плечи и эффективно задействовать грудные мышцы\nЕсли упражнение слишком сложное, начните с варианта с колен или с опорой руками на возвышение 💪',

  [normalizeExerciseName('Resistance Band Chest Press')]:
    'Техника выполнения\n1. Позиция\nРазместите резинку за спиной на уровне груди и возьмите её концы в руки.\n\n2. Исходное положение\nВстаньте в разножку или сядьте прямо. Руки на уровне груди, локти согнуты, в резинке есть натяжение.\n\n3. Движение\nВыпрямляйте руки вперёд, удерживая движение на уровне груди, до полного разгибания.\n\n4. Верхняя точка\nВ полностью выпрямленном положении дополнительно сожмите грудные мышцы и удерживайте 1 секунду.\n\n5. Возврат\nМедленно согните руки и верните их в исходное положение.\n\n6. Дыхание\nВыдох при выжимании, вдох при возврате.\n\nКлючевые моменты\nСопротивление резинки увеличивается по мере выпрямления рук — максимальная нагрузка в конечной точке\nСохраняйте стабильность корпуса, избегайте прогиба в пояснице\nДля увеличения нагрузки используйте более плотную резинку или сложите её вдвое 💪',

  [normalizeExerciseName('Resistance Band Rows')]:
    'Техника выполнения\n1. Позиция\nСядьте на пол, вытянув ноги вперёд (или встаньте). Закрепите резинку на уровне корпуса или за стопы.\n\n2. Исходное положение\nВозьмитесь за концы резинки, руки вытянуты вперёд, есть лёгкое натяжение. Спина ровная, грудная клетка раскрыта.\n\n3. Движение\nТяните резинку к нижней части рёбер, уводя локти назад. Сводите лопатки.\n\n4. Верхняя точка\nЗадержитесь на 1 секунду, удерживая сведённые лопатки.\n\n5. Возврат\nМедленно выпрямите руки, возвращаясь в исходное положение, сохраняя натяжение резинки.\n\n6. Дыхание\nВыдох при тяге, вдох при возврате.\n\nКлючевые моменты\nСохраняйте ровную спину, избегайте округления\nОсновная работа выполняется мышцами спины, а не только руками\nДля увеличения нагрузки используйте более жёсткую резинку или уменьшите её длину 💪',

  [normalizeExerciseName('stend Dumbbell/Bottle Row')]:
    'Техника выполнения\n1. Позиция\nВстаньте, поставив стопы на ширину таза, удерживая по гантели или бутылке в каждой руке. Наклонитесь вперёд примерно на 30-45°, сохраняя ровную спину.\n\n2. Исходное положение\nКорпус стабилен, грудная клетка раскрыта, руки опущены вниз под плечами. Колени слегка согнуты.\n\n3. Движение\nТяните отягощение к нижней части рёбер, уводя локти назад. Локти держите близко к корпусу.\n\n4. Верхняя точка\nЗадержитесь на 1 секунду, сводя лопатки.\n\n5. Возврат\nМедленно опустите отягощение вниз до полного выпрямления рук, не округляя спину.\n\n6. Дыхание\nВыдох при тяге, вдох при опускании.\n\nКлючевые моменты\nСохраняйте нейтральное положение спины, избегайте округления поясницы\nТяните локти назад в сторону таза, а не вверх к шее\nКонтролируйте фазу опускания, чтобы сохранять напряжение в мышцах спины 💪',

  [normalizeExerciseName('Band Face Pulls')]:
    'Техника выполнения\n1. Позиция\nЗакрепите резинку на уровне лица (дверь, стойка или опора). Возьмитесь за концы резинки, ладони направлены вниз.\n\n2. Исходное положение\nОтойдите назад, чтобы появилось натяжение. Руки вытянуты вперёд на уровне лица.\n\n3. Движение\nТяните резинку к лицу, уводя локти назад и в стороны. По мере движения разводите концы резинки.\n\n4. Верхняя точка\nВ конечной позиции руки находятся рядом с ушами, локти высоко. Сведите лопатки и удерживайте 1-2 секунды.\n\n5. Возврат\nМедленно выпрямите руки, возвращаясь в исходное положение.\n\n6. Дыхание\nВыдох при тяге, вдох при возврате.\n\nКлючевые моменты\nОдно из лучших упражнений для здоровья плеч — выполняйте регулярно\nЛокти на уровне плеч или выше на протяжении всего движения\nВ верхней точке добавляйте наружную ротацию: руки у ушей, большие пальцы направлены назад 💪',

  [normalizeExerciseName('Lateral Raises (DB/Bottle/Band)')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, удерживая отягощение или резинку в руках по бокам.\n\n2. Исходное положение\nРуки вдоль корпуса, локти слегка согнуты и фиксированы. Плечи опущены.\n\n3. Движение\nПоднимайте руки в стороны до уровня плеч.\n\n4. Верхняя точка\nЗадержитесь на 1 секунду на уровне плеч. Слегка разверните мизинцы вверх для лучшей активации дельтовидных мышц.\n\n5. Возврат\nМедленно опустите руки обратно вдоль корпуса.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nВедите движение локтями, а не кистями\nНе поднимайте руки выше уровня плеч — выше включаются трапециевидные мышцы\nЛёгкий вес и строгая техника эффективнее, чем большой вес с раскачкой 💪',

  [normalizeExerciseName('Front Raises (DB/Bottle/Band)')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, удерживая отягощение или резинку перед бёдрами.\n\n2. Исходное положение\nРуки опущены вниз, локти слегка согнуты. Корпус стабилен.\n\n3. Движение\nПоднимайте руки вперёд и вверх до уровня плеч. Руки остаются почти прямыми.\n\n4. Верхняя точка\nЗадержитесь на уровне плеч на 1 секунду. Сожмите переднюю часть плеч.\n\n5. Возврат\nМедленно опустите руки обратно в исходное положение.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nПоднимайте руки не выше уровня плеч — выше нагрузка смещается на трапециевидные мышцы\nСохраняйте прямое положение корпуса, не отклоняйтесь назад\nМожно выполнять поочерёдно или одновременно обеими руками 💪',

  [normalizeExerciseName('Band Lateral Walks')]:
    'Техника выполнения\n1. Позиция\nНаденьте резинку на уровень щиколоток (сложнее) или чуть выше коленей (проще). Стопы на ширине таза.\n\n2. Исходное положение\nПримите положение полуприседа: колени слегка согнуты, таз отведён назад, корпус стабилен.\n\n3. Движение\nСделайте контролируемый шаг в сторону одной ногой, растягивая резинку.\n\n4. Возврат\nПодтяните вторую ногу, возвращаясь в исходное положение, сохраняя натяжение резинки.\n\n5. Продолжение\nПродолжайте движение в одну сторону заданное количество повторений, затем смените направление.\n\n6. Дыхание\nДышите ровно, не задерживайте дыхание.\n\nКлючевые моменты\nСохраняйте постоянное натяжение резинки — не сводите стопы полностью\nОставайтесь в положении полуприседа, не выпрямляйтесь между шагами\nСтопы направлены вперёд, не разворачивайте их наружу 💪',

  [normalizeExerciseName('Clamshells')]:
    'Техника выполнения\n1. Позиция\nЛягте на бок, согнув колени примерно под углом 45°. Стопы вместе, голова лежит на руке.\n\n2. Исходное положение\nСтопы прижаты друг к другу, корпус слегка стабилизирован. Таз расположен ровно, без завала назад или вперёд.\n\n3. Движение\nПоднимайте верхнее колено вверх, сохраняя стопы вместе.\n\n4. Верхняя точка\nПоднимите колено максимально вверх, не смещая таз. Сожмите ягодицы и удерживайте 1-2 секунды.\n\n5. Возврат\nМедленно опустите колено обратно в исходное положение.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nСтопы остаются вместе на протяжении всего движения — работает только колено\nНе заваливайте таз назад при подъёме колена\nДля усложнения используйте резинку выше колен 💪',

  [normalizeExerciseName('Donkey Kicks')]:
    'Техника выполнения\n1. Позиция\nВстаньте в упор на четвереньках: ладони под плечами, колени под тазом.\n\n2. Исходное положение\nКорпус стабилен, спина в нейтральном положении. Одна нога остаётся опорной, другая — рабочая.\n\n3. Движение\nСохраняя угол около 90° в колене, поднимайте рабочую ногу вверх за счёт движения в тазобедренном суставе. Стопа направлена вверх.\n\n4. Верхняя точка\nВ верхнем положении сожмите ягодицы и удерживайте 1-2 секунды. Таз остаётся ровным, без поворота.\n\n5. Возврат\nМедленно опустите ногу вниз, не касаясь пола. Выполните все повторения и смените сторону.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nСохраняйте нейтральное положение спины, не прогибайтесь в пояснице\nСильно сжимайте ягодицы в верхней точке\nТаз остаётся стабильным, не разворачивайте его в сторону 💪',

  [normalizeExerciseName('Fire Hydrants')]:
    'Техника выполнения\n1. Позиция\nВстаньте в упор на четвереньках: ладони под плечами, колени под тазом.\n\n2. Исходное положение\nКорпус стабилен, спина в нейтральном положении. Рабочая нога согнута, колено на полу.\n\n3. Движение\nСохраняя угол около 90° в колене, отведите ногу в сторону, поднимая её вверх.\n\n4. Верхняя точка\nПоднимите колено до уровня таза. Сожмите ягодицы и удерживайте 1-2 секунды.\n\n5. Возврат\nМедленно опустите колено обратно на пол. Выполните все повторения и смените сторону.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nСохраняйте стабильность корпуса — не переносите вес на противоположную сторону\nОсновная нагрузка приходится на среднюю ягодичную мышцу, которая важна для стабильности таза\nДля увеличения нагрузки используйте утяжелители на голеностоп или резинку выше колен 💪',

  [normalizeExerciseName('Side-Lying Leg Raises')]:
    'Техника выполнения\n1. Позиция\nЛягте на бок, ноги выпрямлены и расположены одна над другой. Голова лежит на руке или ладони.\n\n2. Исходное положение\nТело образует прямую линию. Корпус стабилен.\n\n3. Движение\nПоднимайте верхнюю ногу вверх, сохраняя её прямой. Движение начинается через пятку.\n\n4. Верхняя точка\nПоднимите ногу примерно до 45° или до ощущения работы ягодиц. Задержитесь на 1 секунду.\n\n5. Возврат\nМедленно опустите ногу в исходное положение. Выполните все повторения и смените сторону.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nВедите движение через пятку, а не через носок — это усиливает работу ягодиц\nСохраняйте ровное положение таза, не заваливайтесь назад\nНе поднимайте ногу слишком высоко — важен контроль в рабочей амплитуде 💪',

  [normalizeExerciseName('Single-Leg Glute Bridge')]:
    'Техника выполнения\n1. Позиция\nЛягте на спину, согните колени, стопы на полу. Одну ногу выпрямите и поднимите вверх.\n\n2. Исходное положение\nОдна стопа остаётся на полу ближе к ягодицам. Корпус стабилен.\n\n3. Движение\nОтталкивайтесь пяткой опорной ноги и поднимайте таз вверх. Выпрямленная нога остаётся поднятой.\n\n4. Верхняя точка\nТаз на одном уровне, без перекоса. Сильно сожмите ягодицы и удерживайте 2 секунды.\n\n5. Возврат\nМедленно опустите таз вниз. Выполните все повторения и смените ногу.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nСохраняйте ровное положение таза — не допускайте провала на одну сторону\nУпражнение помогает устранить дисбаланс силы между правой и левой стороной\nЕсли сложно удерживать таз ровно, начните с классического ягодичного моста 💪',

  [normalizeExerciseName('Wall Glute Squeeze (Isometric)')]:
    'Техника выполнения\n1. Позиция\nНаденьте мини-резинку чуть выше коленей и встаньте, слегка опираясь спиной о стену. Стопы на ширине таза, колени слегка согнуты.\n\n2. Исходное положение\nСлегка отведите таз назад к стене, корпус стабилен. Сохраняйте натяжение резинки.\n\n3. Движение\nСожмите ягодицы и разведите колени в стороны, преодолевая сопротивление резинки. Движение небольшое и контролируемое.\n\n4. Верхняя точка\nВ максимальном безопасном положении удерживайте 1-2 секунды, сохраняя напряжение в ягодицах и резинке.\n\n5. Возврат\nМедленно сведите колени, не теряя натяжения резинки, и повторите движение.\n\n6. Дыхание\nДышите ровно, не задерживайте дыхание.\n\nКлючевые моменты\nСохраняйте лёгкое давление в стену, не прогибайтесь в пояснице\nДвижение идёт от тазобедренного сустава и ягодиц, а не за счёт разворота стоп\nПоддерживайте постоянное натяжение резинки на протяжении всего упражнения 💪',

  [normalizeExerciseName('Band Pull-Aparts')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, удерживая резинку перед собой на уровне плеч обеими руками.\n\n2. Исходное положение\nРуки вытянуты вперёд, есть лёгкое натяжение резинки. Кисти примерно на ширине плеч.\n\n3. Движение\nРазводите руки в стороны, растягивая резинку и сводя лопатки.\n\n4. Верхняя точка\nРезинка касается или почти касается груди. Сведите лопатки и удерживайте 1 секунду.\n\n5. Возврат\nМедленно вернитесь в исходное положение, сохраняя контроль.\n\n6. Дыхание\nВыдох при разведении, вдох при возврате.\n\nКлючевые моменты\nДержите руки на уровне плеч и почти прямыми на протяжении всего движения\nСосредоточьтесь на сведении лопаток, а не на работе руками\nОтличное упражнение для разминки и здоровья плеч — можно выполнять регулярно 💪',

  [normalizeExerciseName('Concentration Curl')]:
    'Техника выполнения\n1. Позиция\nСядьте на стул или скамью, ноги разведены. Возьмите гантель, бутылку или любой подручный вес в одну руку.\n\n2. Исходное положение\nУпритесь локтем рабочей руки во внутреннюю поверхность бедра. Рука полностью выпрямлена, отягощение находится чуть выше пола.\n\n3. Движение\nСгибайте руку, поднимая отягощение к плечу. Верхняя часть руки остаётся прижатой к бедру.\n\n4. Верхняя точка\nСильно сожмите бицепс и удерживайте 1-2 секунды.\n\n5. Возврат\nМедленно опустите отягощение до полного выпрямления руки. Выполните все повторения и смените руку.\n\n6. Дыхание\nВыдох при сгибании, вдох при опускании.\n\nКлючевые моменты\nФиксация локтя на бедре исключает инерцию и изолирует работу бицепса\nСосредоточьтесь на максимальном сокращении в верхней точке\nОтличное упражнение для проработки каждой руки отдельно и устранения дисбаланса 💪',

  [normalizeExerciseName('door/bodyweight row')]:
    'Техника выполнения\n1. Позиция\nВстаньте лицом к дверному проёму и возьмитесь руками за его края на уровне груди.\n\n2. Исходное положение\nОтклонитесь назад, выпрямив руки. Тело образует прямую линию от головы до пят.\n\n3. Движение\nТяните корпус к дверному проёму, уводя локти назад. Грудная клетка раскрыта.\n\n4. Верхняя точка\nПодведите грудь ближе к проёму, сведите лопатки и удерживайте 1 секунду.\n\n5. Возврат\nМедленно выпрямите руки и вернитесь в исходное положение.\n\n6. Дыхание\nВыдох при тяге, вдох при возврате.\n\nКлючевые моменты\nСохраняйте прямую линию тела, не сгибайтесь в тазу\nОсновная работа — за счёт мышц спины, а не рук\nЧем сильнее отклонение назад, тем выше нагрузка\nПлечи держите опущенными, не поднимайте их к ушам 💪',

  [normalizeExerciseName('Door Rows (Towel Rows)')]:
    'Техника выполнения\n1. Позиция\nВстаньте лицом к дверному проёму и возьмитесь руками за его края на уровне груди.\n\n2. Исходное положение\nОтклонитесь назад, выпрямив руки. Тело образует прямую линию от головы до пят.\n\n3. Движение\nТяните корпус к дверному проёму, уводя локти назад. Грудная клетка раскрыта.\n\n4. Верхняя точка\nПодведите грудь ближе к проёму, сведите лопатки и удерживайте 1 секунду.\n\n5. Возврат\nМедленно выпрямите руки и вернитесь в исходное положение.\n\n6. Дыхание\nВыдох при тяге, вдох при возврате.\n\nКлючевые моменты\nСохраняйте прямую линию тела, не сгибайтесь в тазу\nОсновная работа — за счёт мышц спины, а не рук\nЧем сильнее отклонение назад, тем выше нагрузка\nПлечи держите опущенными, не поднимайте их к ушам 💪',

  [normalizeExerciseName('Band Squats')]:
    '1. Подготовка\nНаденьте резинку сопротивления чуть выше коленей или встаньте на длинную резинку, удерживая её в руках. Поставьте стопы на ширину плеч. При необходимости возьмите дополнительный вес — гантели или подручный предмет (например, бутылку с водой).\n2. Исходное положение\nКорпус напряжен, грудная клетка раскрыта.\n3. Опускание\nОтведите таз назад и опуститесь в присед, активно разводя колени наружу против сопротивления резинки.\n4. Нижняя позиция\nОпуститесь до параллели бедер с полом или чуть ниже. Удерживайте колени разведенными наружу против сопротивления резинки.\n5. Подъем\nПоднимайтесь за счет давления пятками в пол, сохраняя наружное давление коленями на резинку на протяжении всего движения.\n\nКлючевые моменты:\n- Резинка формирует правильную траекторию коленей, заставляя активно давить коленями наружу.\n- Отлично подходит для активации ягодичных мышц и коррекции завала коленей внутрь,в случае использования маленькой коленки над коленями.\n- Можно использовать как разминку перед тяжелыми приседаниями.',

  [normalizeExerciseName('Bodyweight Squat')]:
    'Техника выполнения\n1. Позиция\nВстаньте, поставив стопы на ширину плеч, носки слегка развернуты наружу. Руки перед собой, скрещены на груди или за головой.\n\n2. Исходное положение\nГрудная клетка раскрыта, корпус стабилен, вес равномерно распределён по стопам.\n\n3. Движение\nОтведите таз назад и начните сгибать колени, опускаясь вниз. Сохраняйте грудную клетку раскрытой, колени направлены по линии носков.\n\n4. Нижняя точка\nОпуститесь до параллели бёдер с полом или ниже — в пределах вашей подвижности. Не допускайте завала коленей внутрь.\n\n5. Возврат\nОтталкивайтесь пятками и серединой стопы, возвращаясь в исходное положение. В верхней точке дополнительно сожмите ягодицы.\n\n6. Дыхание\nВыдох на подъёме, вдох на опускании.\n\nКлючевые моменты\nПятки остаются на полу на протяжении всего движения — при отрыве работайте над подвижностью голеностопа\nКолени направлены в ту же сторону, что и носки\nСохраняйте прямое положение корпуса, избегайте округления спины',

  [normalizeExerciseName('Step-Ups')]:
    'Техника выполнения\n1. Позиция\nВстаньте перед устойчивой скамьёй, платформой или степом. Стопы на ширине таза, корпус стабилен.\n\n2. Исходное положение\nПоставьте одну стопу полностью на платформу. Вся стопа в опоре, не только носок.\n\n3. Движение\nОтталкивайтесь пяткой опорной ноги и поднимайте тело вверх. Не помогайте задней ногой — основная работа выполняется передней ногой.\n\n4. Верхняя точка\nПоднимитесь на платформу, поставив вторую ногу рядом. Корпус прямой, таз на одном уровне.\n\n5. Возврат\nСпускайтесь по одной ноге, сохраняя контроль и равновесие.\n\n6. Дыхание\nВыдох при подъёме, вдох при спуске.\n\nКлючевые моменты\nОтталкивайтесь пяткой рабочей ноги для максимальной активации ягодиц\nСохраняйте вертикальное положение корпуса, избегайте наклона вперёд\nБолее высокая платформа увеличивает амплитуду движения и нагрузку на ягодицы 💪',

  [normalizeExerciseName('Sumo Squat')]:
    'Техника выполнения\n1. Позиция\nВстаньте в широкую стойку (примерно в 1,5-2 раза шире плеч), носки развернуты примерно на 45°.\n\n2. Исходное положение\nГрудная клетка раскрыта, корпус стабилен. Руки перед собой или на поясе.\n\n3. Движение\nОтведите таз назад и вниз, сгибая колени и направляя их в сторону носков.\n\n4. Нижняя точка\nОпуститесь до параллели бёдер с полом. Старайтесь сохранять максимально вертикальное положение корпуса.\n\n5. Возврат\nОтталкивайтесь пятками и возвращайтесь в исходное положение. В верхней точке дополнительно сожмите ягодицы.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nКолени направлены наружу и движутся по линии носков\nШирокая стойка усиливает нагрузку на внутреннюю поверхность бедра и ягодицы\nСохраняйте вертикальное положение корпуса, избегайте наклона вперёд',

  [normalizeExerciseName('Walking Lunges')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо в начале пространства. Стопы на ширине таза, корпус стабилен. Руки на поясе или вдоль тела.\n\n2. Исходное положение\nСохраняйте прямое положение корпуса, подготовьтесь к шагу вперёд.\n\n3. Движение\nСделайте шаг вперёд и опуститесь в выпад, сгибая обе ноги примерно до 90 градусов. Затем оттолкнитесь пяткой передней ноги и перенесите заднюю ногу вперёд, переходя в следующий шаг.\n\n4. Нижняя точка\nВ каждом шаге заднее колено опускается почти до пола, голень передней ноги остаётся близкой к вертикали.\n\n5. Возврат\nДвигайтесь вперёд, чередуя ноги, сохраняя контроль и равновесие.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nВыпады в движении развивают координацию, баланс и выносливость\nСохраняйте одинаковую длину шага: слишком короткий перегружает колени, слишком длинный усложняет подъём\nДвигайтесь в ровном, контролируемом темпе, без спешки',

  [normalizeExerciseName('Single-Leg RDL')]:
    'Техника выполнения\n1. Позиция\nВстаньте на одну ногу, сохраняя лёгкий сгиб в колене. В противоположной руке можно держать отягощение.\n\n2. Исходное положение\nКорпус прямой, корпус стабилен. Удерживайте баланс на опорной ноге.\n\n3. Движение\nНаклоняйтесь вперёд за счёт тазобедренного сустава, одновременно уводя свободную ногу назад. Корпус и нога движутся как единая линия.\n\n4. Нижняя точка\nОпуститесь до положения, при котором корпус и свободная нога находятся примерно параллельно полу. Почувствуйте растяжение задней поверхности бедра опорной ноги.\n\n5. Возврат\nВыведите таз вперёд и вернитесь в исходное положение, опуская свободную ногу.\n\n6. Дыхание\nВыдох при подъёме, вдох при наклоне.\n\nКлючевые моменты\nСохраняйте ровную спину, избегайте округления\nКолено опорной ноги остаётся слегка согнутым\nУпражнение развивает баланс, гибкость задней поверхности бедра и силу ягодиц 💪',

  [normalizeExerciseName('Romanian Deadlift (Bottle/Backpack)')]:
    'Техника выполнения\n1. Позиция\nВстаньте, поставив стопы на ширину таза. Держите отягощение перед бёдрами — гантели, бутылки с водой или рюкзак с весом.\n\n2. Исходное положение\nКолени слегка согнуты и остаются в этом положении. Корпус стабилен, спина ровная.\n\n3. Движение\nОтведите таз назад и опускайте вес вдоль ног за счёт сгибания в тазобедренном суставе. Держите отягощение максимально близко к ногам.\n\n4. Нижняя точка\nОпуститесь до ощущения выраженного растяжения задней поверхности бедра. Не округляйте спину.\n\n5. Возврат\nВыведите таз вперёд и вернитесь в исходное положение. В верхней точке дополнительно сожмите ягодицы.\n\n6. Дыхание\nВыдох при подъёме, вдох при наклоне.\n\nКлючевые моменты\nЭто движение из тазобедренного сустава, а не присед — угол в коленях остаётся практически неизменным\nДержите отягощение близко к ногам для правильной механики\nИспользуйте любой доступный вес: рюкзак с книгами, бутылки с водой и т.д. 💪',

  [normalizeExerciseName('Diamond Push-Ups')]:
    'Техника выполнения\n1. Позиция\nПоставьте ладони близко друг к другу, соединив большие и указательные пальцы так, чтобы образовалась форма «алмаза».\n\n2. Исходное положение\nВытяните ноги назад, тело образует прямую линию от головы до пят. Корпус стабилен, руки выпрямлены.\n\n3. Движение\nСгибайте руки в локтях, опуская грудную клетку к ладоням. Локти держите близко к корпусу.\n\n4. Нижняя точка\nОпуститесь до положения, при котором грудная клетка почти касается ладоней.\n\n5. Возврат\nОттолкнитесь ладонями и полностью выпрямите руки, возвращаясь в исходное положение. Основная нагрузка — на трицепсы.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nУзкая постановка рук максимально увеличивает нагрузку на трицепсы\nЛокти направлены вдоль корпуса — их разведение снижает нагрузку на трицепсы\nЕсли упражнение слишком сложное, немного расширьте постановку рук, сохраняя её уже ширины плеч 💪',

  [normalizeExerciseName('Pike Push-Ups')]:
    'Техника выполнения\n1. Позиция\nПримите положение упора лёжа, затем шагами подтяните стопы ближе к рукам, поднимая таз вверх и формируя положение «перевёрнутой V».\n\n2. Исходное положение\nРуки на ширине плеч, таз высоко, голова между руками, взгляд направлен в пол. В тазобедренных суставах сохраняется угол около 90°.\n\n3. Движение\nСгибайте руки в локтях, опуская макушку головы к полу. Локти направлены под углом около 45°.\n\n4. Нижняя точка\nОпуститесь до положения, при котором голова почти касается пола.\n\n5. Возврат\nОттолкнитесь ладонями и выпрямите руки, возвращаясь в исходное положение.\n\n6. Дыхание\nВыдох при подъёме, вдох при опускании.\n\nКлючевые моменты\nЭто вариант жима на плечи с собственным весом — чем более вертикален корпус, тем выше нагрузка\nСохраняйте высокий таз на протяжении всего движения, не переходите в классические отжимания\nДля усложнения поставьте стопы на возвышение — это увеличит нагрузку и приблизит упражнение к отжиманиям в стойке на руках 💪',

  [normalizeExerciseName('Bottle Floor Press')]:
    'Техника выполнения\n1. Позиция\nЛягте на пол, удерживая по бутылке (или гантели) в каждой руке. Колени согнуты, стопы на полу.\n\n2. Исходное положение\nРуки на уровне груди, локти касаются пола, запястья находятся над локтями.\n\n3. Движение\nВыжимайте отягощение вверх, полностью выпрямляя руки.\n\n4. Верхняя точка\nВ верхней точке дополнительно напрягите грудные мышцы, слегка сводя руки друг к другу.\n\n5. Возврат\nМедленно опустите отягощение вниз, пока локти мягко не коснутся пола. Сделайте короткую паузу и повторите движение.\n\n6. Дыхание\nВыдох при жиме, вдох при опускании.\n\nКлючевые моменты\nПол ограничивает амплитуду движения и снижает нагрузку на плечевые суставы\nСохраняйте нейтральное положение запястий, не допускайте их залома назад\nОтличный вариант жима на грудные мышцы в домашних условиях при отсутствии скамьи 💪',

  [normalizeExerciseName('Glute Bridge')]:
    'Задействованные мышцы\n\nЯгодицы, задняя поверхность бедра\n\nТехника выполнения\n1. Позиция\n\nЛягте на спину, согните колени, стопы на полу на ширине таза, ближе к ягодицам.\n\n2. Исходное положение\n\nРуки вдоль корпуса, ладони направлены вниз. Корпус стабилен.\n\n3. Подъём\n\nОтталкивайтесь пятками и поднимайте таз вверх. В верхней точке тело образует прямую линию от плеч до колен.\n\n4. Верхняя точка\n\nСильно сожмите ягодицы и удерживайте положение 2 секунды. Не допускайте переразгибания в пояснице.\n\n5. Опускание\n\nМедленно опустите таз обратно на пол.\n\nКлючевые моменты\nОтталкивайтесь пятками, а не носками — это усиливает работу ягодиц\nМаксимально сжимайте ягодицы в верхней точке\nНе прогибайтесь в пояснице — сохраняйте прямую линию от плеч до колен',

  [normalizeExerciseName('Bulgarian Split Squat')]:
    'Задействованные мышцы\n\nЯгодицы, квадрицепсы, задняя поверхность бедра\n\nТехника выполнения\n1. Позиция\n\nВстаньте примерно в 60 см перед скамьёй или стулом. Положите верхнюю часть стопы задней ноги на опору.\n\n2. Исходное положение\n\nПередняя стопа полностью в опоре, корпус прямой, мышцы кора активны. Руки на поясе или с отягощением.\n\n3. Опускание\n\nСгибайте переднюю ногу, опуская заднее колено к полу. Сохраняйте голень передней ноги близкой к вертикали.\n\n4. Нижняя точка\n\nОпуститесь до параллели бедра передней ноги с полом. Заднее колено — чуть выше пола.\n\n5. Подъём\n\nПоднимайтесь через пятку передней ноги, возвращаясь в исходное положение. Сохраняйте корпус прямым на протяжении всего движения.\n\nКлючевые моменты\nОсновной вес на передней ноге — задняя служит для баланса\nГолень передней ноги остаётся максимально вертикальной, колено не уходит далеко вперёд за носок\nОтличное упражнение для развития силы и баланса на одной ноге',

  [normalizeExerciseName('Bulgarian Split Squat (Gym)')]:
    'Техника выполнения\n1. Позиция\nВстаньте в шаге от скамьи. Поставьте верх стопы задней ноги на скамью, в руки возьмите гантели по бокам.\n\n2. Исходное положение\nПередняя стопа полностью в опоре, корпус собран, таз ровный, плечи над тазом.\n\n3. Опускание\nОпускайтесь строго вниз, одновременно сгибая колено и тазобедренный сустав передней ноги. Заднее колено движется к полу под контролем.\n\n4. Нижняя точка\nОпускайтесь до уровня, где сохраняется полный контакт передней стопы с полом и нейтральная спина.\n\n5. Подъём\nПоднимайтесь через пятку и середину передней стопы, без толчка задней ногой.\n\n6. Дыхание\nВдох при опускании, выдох в усилии при подъёме.\n\nКлючевые моменты\nДля зала важны стабильность таза и контроль веса, а не максимальная глубина\nНе заваливайте корпус вперёд и не переносите работу на заднюю ногу\nПовышайте вес только при одинаково чистой технике на обе стороны',

  [normalizeExerciseName('Forward Lunges')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, стопы на ширине таза, корпус стабилен.\n\n2. Шаг вперёд\nСделайте широкий шаг вперёд одной ногой и начните опускаться.\n\n3. Нижняя точка\nСогните обе ноги примерно до 90 градусов. Голень передней ноги остаётся почти вертикальной. Заднее колено — чуть выше пола.\n\n4. Возврат\nОттолкнитесь передней ногой и вернитесь в исходное положение.\n\n5. Смена ног\nПовторите с другой ноги.\n\nКлючевые моменты\nВыпады вперёд сильнее нагружают квадрицепсы и требуют большего контроля при замедлении движения по сравнению с выпадами назад\nСохраняйте вертикальное положение корпуса и стабильность корпуса на протяжении всего движения\nДелайте достаточно широкий шаг, чтобы колено передней ноги не уходило далеко вперёд за носок',

  [normalizeExerciseName('Reverse Lunges')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, стопы на ширине таза, корпус стабилен. Руки на поясе или вдоль тела.\n\n2. Шаг назад\nСделайте шаг одной ногой назад примерно на 60-90 см и начните опускаться, сгибая обе ноги.\n\n3. Нижняя точка\nОпуститесь до угла около 90 градусов в обоих коленях. Заднее колено — чуть выше пола. Голень передней ноги остаётся вертикальной.\n\n4. Возврат\nОттолкнитесь пяткой передней ноги и вернитесь в исходное положение, подтягивая заднюю ногу вперёд.\n\n5. Смена ног\nПовторите с другой ноги.\n\nКлючевые моменты\nВыпады назад мягче для коленей по сравнению с выпадами вперёд — предпочтительны при дискомфорте в коленях\nОтталкивайтесь пяткой передней ноги, а не носком\nСохраняйте вертикальное положение корпуса, избегайте наклона вперёд',

  [normalizeExerciseName('Assisted Pull-ups (machine)')]:
    '1. Подготовка\nУстановите вес помощи в тренажере (чем больше вес, тем легче). Встаньте или встаньте коленями на платформу и возьмитесь за рукояти.\n2. Исходное положение\nВис на полностью выпрямленных руках, плечи активные (опущены и сведены назад), корпус напряжен.\n3. Подтягивание\nТяните себя вверх, ведя локти вниз. Фокус на широчайших, а не только на руках.\n4. Верхняя позиция\nПодтянитесь до положения, когда подбородок выше рукоятей. Вверху сожмите широчайшие.\n5. Опускание\nМедленно опуститесь обратно до полного выпрямления рук под контролем.\n\nКлючевые моменты:\n- Постепенно уменьшайте вес помощи, чтобы перейти к подтягиваниям без поддержки.\n- Следите за чистой техникой: полное выпрямление внизу, подбородок выше рукоятей вверху.\n- Тренажер имитирует обычные подтягивания, поэтому используйте его для отработки правильной механики.',

  [normalizeExerciseName('Chest-supported Dumbbell Row')]:
    '1. Подготовка\nУстановите наклон скамьи примерно 30-45 градусов. Лягте на нее грудью вниз, гантели свисают вниз.\n2. Исходное положение\nРуки полностью выпрямлены, ладони смотрят друг на друга. Грудь плотно прижата к скамье.\n3. Тяга\nТяните обе гантели вверх, ведя локти назад к тазу. Сведите лопатки.\n4. Верхняя позиция\nВверху зафиксируйтесь с сведенными лопатками на 1 секунду.\n5. Опускание\nМедленно опустите гантели до полного выпрямления рук.\n\nКлючевые моменты:\n- Опора грудью убирает инерцию и снижает нагрузку на поясницу, поэтому акцент идет на мышцы спины.\n- Отличный вариант при проблемах с поясницей, когда трудно делать тяги в наклоне.\n- На протяжении всего подхода сохраняйте контакт груди со скамьей.',

  [normalizeExerciseName('TRX Rows')]:
    '1. Подготовка\nВозьмитесь за рукояти TRX хватом сверху. Отклонитесь назад на выпрямленных руках, тело в прямой линии от головы до пяток.\n2. Исходное положение\nСтопы выставлены вперед (чем ближе к точке крепления, тем сложнее). Корпус прямой, пресс и ягодицы напряжены, стропы натянуты.\n3. Тяга\nПодтягивайте грудь к рукоятям, ведя локти назад. Сводите лопатки.\n4. Верхняя позиция\nВ верхней точке короткая фиксация со сведенными лопатками на 1 секунду.\n5. Опускание\nМедленно выпрямите руки и вернитесь в исходное положение под контролем.\n\nКлючевые моменты:\n- Чтобы увеличить сложность, ставьте стопы ближе к точке крепления.\n- Держите тело жестким: не провисайте в тазу и не поднимайте таз домиком.\n- Это эффективная тяга с собственным весом, которую можно выполнять везде, где есть TRX или петли.',

  [normalizeExerciseName('Upright Row (barbell/dumbbell/cable)')]:
    '1. Подготовка\nВстаньте прямо, удерживая штангу, гантели или рукоять блока перед бедрами. Хват немного уже ширины плеч.\n2. Исходное положение\nРуки выпрямлены, корпус напряжен, плечи опущены.\n3. Тяга\nТяните вес вверх вдоль корпуса, ведя движение локтями. Локти идут вверх и в стороны.\n4. Верхняя позиция\nОстановитесь, когда локти достигнут примерно уровня плеч (верхней части груди). Не поднимайте выше, чтобы не перегружать плечевой сустав.\n5. Опускание\nМедленно опустите вес в исходное положение под контролем.\n\nКлючевые моменты:\n- Ведите движение локтями, а не кистями: так лучше нагружаются дельтовидные и трапециевидные мышцы.\n- Не поднимайте выше уровня плеч: слишком высокая тяга может привести к импинджменту плеча.\n- Более широкий хват смещает акцент на среднюю дельту, более узкий — на трапеции.',

  [normalizeExerciseName('Leg Slides (towel leg curls)')]:
    'Техника выполнения\n1. Позиция\nЛягте на спину, пятки поставьте на полотенца или скользящую поверхность. Колени слегка согнуты, руки вдоль корпуса.\n\n2. Исходное положение\nПоднимите таз в положение моста, корпус стабилен.\n\n3. Движение\nМедленно выпрямляйте ноги, уводя пятки от себя, сохраняя таз максимально высоко.\n\n4. Возврат\nСгибайте ноги и подтягивайте пятки к ягодицам за счет задней поверхности бедра.\n\n5. Контроль\nДержите движение плавным, без рывков, до конца подхода.\n\nКлючевые моменты\nГлавная нагрузка на бицепс бедра, а не на поясницу\nЕсли таз опускается, уменьшите амплитуду и замедлите темп\nЧем медленнее возврат, тем сильнее включаются мышцы задней поверхности бедра',

  [normalizeExerciseName('Goblet Squat')]:
    'Техника выполнения\n1. Позиция\nВстаньте на ширине плеч, удерживайте гантель или гирю у груди.\n\n2. Исходное положение\nЛокти направлены вниз, корпус собран, стопы полностью в опоре.\n\n3. Опускание\nОтведите таз назад и вниз, сгибая колени по линии носков.\n\n4. Подъем\nПоднимайтесь через пятки и середину стопы, сохраняя спину ровной.\n\n5. Завершение\nВ верхней точке полностью выпрямитесь и стабилизируйте корпус.\n\nКлючевые моменты\nВес у груди помогает держать более вертикальный корпус\nНе заваливайте колени внутрь\nГлубина приседа только при сохранении нейтральной спины',

  [normalizeExerciseName('Reverse / Forward Lunges')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, стопы на ширине таза, корпус стабилен.\n\n2. Шаг\nВыполните шаг вперед или назад и опуститесь в выпад.\n\n3. Нижняя точка\nОбе ноги согнуты примерно под 90 градусов, переднее колено направлено по носку.\n\n4. Возврат\nОттолкнитесь передней ногой и вернитесь в исходное положение.\n\n5. Чередование\nПовторяйте, меняя сторону и направление выпада.\n\nКлючевые моменты\nВыпад назад мягче для коленей, выпад вперед сильнее грузит квадрицепс\nДержите корпус вертикально, без завала вперед\nНе допускайте короткого шага, при котором колено уходит далеко за носок',

  [normalizeExerciseName('Leg Adduction Machine')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажер, разместите внутреннюю часть бедер на подушках.\n\n2. Исходное положение\nСпина прижата к опоре, корпус стабилен, ноги разведены.\n\n3. Сведение\nСводите бедра внутрь плавно, без рывка.\n\n4. Пиковое сокращение\nНа сведении задержитесь на 1 секунду и сожмите приводящие мышцы.\n\n5. Возврат\nМедленно верните ноги в исходную ширину под контролем.\n\nКлючевые моменты\nНе помогайте движению корпусом\nКонтролируйте отрицательную фазу\nРаботайте в комфортной амплитуде без боли в паховой области',

  [normalizeExerciseName('Cable Hip Abduction')]:
    'Техника выполнения\n1. Позиция\nЗакрепите манжету на лодыжке рабочей ноги и встаньте боком к нижнему блоку.\n\n2. Исходное положение\nОпорная нога слегка согнута, корпус стабилен, таз ровный.\n\n3. Отведение\nОтведите рабочую ногу в сторону по дуге, не разворачивая корпус.\n\n4. Верхняя точка\nСделайте короткую паузу и сожмите среднюю ягодичную мышцу.\n\n5. Возврат\nВерните ногу обратно медленно, сохраняя натяжение троса.\n\nКлючевые моменты\nДвижение идет из тазобедренного сустава, не из поясницы\nНе наклоняйте корпус в противоположную сторону\nНебольшой рабочий вес и строгий контроль эффективнее читинга',

  [normalizeExerciseName('Plate-loaded Hip Abduction')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажер, разместите внешнюю часть бедер на подушках и зафиксируйте корпус.\n\n2. Исходное положение\nКолени сведены, стопы в опоре, спина прижата к спинке.\n\n3. Разведение\nРазводите колени в стороны в контролируемом темпе.\n\n4. Пиковое сокращение\nВ крайней точке задержитесь на 1 секунду, максимально напрягая ягодицы.\n\n5. Возврат\nМедленно сведите колени, не бросая вес.\n\nКлючевые моменты\nНе помогайте движению раскачкой корпуса\nПолезно для активации средней ягодичной и стабилизации таза\nДержите постоянное напряжение в мышцах на всем подходе',

  [normalizeExerciseName('Hip Abduction Machine')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажер для отведения бедра, ноги внутри подушек.\n\n2. Исходное положение\nКорпус устойчив, живот напряжен, спина прижата.\n\n3. Движение\nРазводите бедра в стороны плавно, без ускорений.\n\n4. Верхняя точка\nУдержите разведение 1 секунду, концентрируясь на ягодицах.\n\n5. Возврат\nПод контролем верните бедра в исходную позицию.\n\nКлючевые моменты\nНе сводите колени полностью между повторами\nНе разгружайте вес внизу\nСтабильный темп и пауза в пике дают лучший отклик мышц',

  [normalizeExerciseName('Sissy Squats')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, при необходимости держитесь рукой за опору для баланса.\n\n2. Исходное положение\nПоднимите пятки и удерживайтесь на носках, корпус в линии от колен до головы.\n\n3. Опускание\nСгибайте колени, уводя их вперед, и отклоняйте корпус назад как единый блок.\n\n4. Нижняя точка\nОпускайтесь до контролируемой глубины с сильным напряжением квадрицепса.\n\n5. Подъем\nВернитесь вверх, разгибая колени и сохраняя контроль.\n\nКлючевые моменты\nЭто упражнение с сильной нагрузкой на коленный сустав, выполняйте аккуратно\nНе проваливайтесь вниз резко\nИспользуйте опору, если не хватает баланса',

  [normalizeExerciseName('Nordic Curl')]:
    'Техника выполнения\n1. Позиция\nВстаньте на колени, зафиксируйте стопы под опорой или с помощью партнера.\n\n2. Исходное положение\nКорпус прямой от колен до плеч, пресс напряжен.\n\n3. Опускание\nМедленно опускайте корпус вперед, сопротивляясь движению за счет бицепса бедра.\n\n4. Нижняя точка\nВнизу подстрахуйте себя руками, чтобы не удариться о пол.\n\n5. Возврат\nОттолкнитесь руками и помогите себе вернуться в старт, сохраняя напряжение задней поверхности бедра.\n\nКлючевые моменты\nОдна из самых сильных нагрузок на бицепс бедра\nКонтролируйте негатив максимально медленно\nДаже частичная амплитуда уже эффективна',

  [normalizeExerciseName('Good Morning')]:
    'Техника выполнения\n1. Позиция\nВстаньте на ширине плеч. Разместите штангу на верхней части спины (или используйте резинку/вес тела).\n\n2. Исходное положение\nКолени слегка согнуты, корпус напряжен, спина нейтральная.\n\n3. Наклон\nОтводите таз назад и наклоняйте корпус вперед за счет тазобедренного сустава.\n\n4. Нижняя точка\nОпускайтесь до контролируемого натяжения задней поверхности бедра, без округления спины.\n\n5. Подъем\nВыведите таз вперед и вернитесь в вертикаль, сжимая ягодицы вверху.\n\nКлючевые моменты\nДвижение идет из таза, а не из поясницы\nСохраняйте нейтральную спину и раскрытую грудную клетку\nНачинайте с легкого веса и повышайте нагрузку только при стабильной технике',

  [normalizeExerciseName('Good Mornings')]:
    'Техника выполнения\n1. Позиция\nВстаньте на ширине плеч, руки за головой или держите легкое отягощение на верхней части спины.\n\n2. Исходное положение\nКолени слегка согнуты, спина ровная, корпус напряжен.\n\n3. Наклон\nОтводите таз назад и наклоняйте корпус вперед за счет тазобедренного сустава.\n\n4. Нижняя точка\nОпускайтесь до комфортного натяжения задней поверхности бедра без округления спины.\n\n5. Подъем\nВернитесь в вертикаль, сжимая ягодицы в верхней точке.\n\nКлючевые моменты\nДвижение из тазобедренного сустава, не из поясницы\nСпина остается нейтральной всю амплитуду\nЛучше меньший вес и идеальная техника',

  [normalizeExerciseName('Reverse Hyperextensions')]:
    'Техника выполнения\n1. Позиция\nЛягте животом на скамью или высокую опору так, чтобы ноги свободно свисали вниз.\n\n2. Исходное положение\nРуками крепко держитесь за опору, поясница нейтральна.\n\n3. Подъем\nПоднимайте обе ноги назад и вверх за счет ягодиц и задней поверхности бедра.\n\n4. Верхняя точка\nЗадержитесь на 1 секунду без переразгибания в пояснице.\n\n5. Опускание\nМедленно опустите ноги вниз под контролем.\n\nКлючевые моменты\nНе делайте рывков за счет поясницы\nФокус на ягодицах и бицепсе бедра\nУмеренная амплитуда безопаснее, чем чрезмерно высокая',

  [normalizeExerciseName('Jefferson Deadlift')]:
    'Техника выполнения\n1. Позиция\nВстаньте над штангой в разноименной стойке: одна нога впереди грифа, другая сзади.\n\n2. Исходное положение\nНаклонитесь и возьмите штангу руками с двух сторон, спина нейтральна, корпус напряжен.\n\n3. Подъем\nПоднимайте штангу, одновременно разгибая колени и таз, сохраняя корпус стабильным.\n\n4. Верхняя точка\nПолностью выпрямитесь без переразгибания поясницы.\n\n5. Опускание\nОпустите штангу обратно под контролем по той же траектории.\n\nКлючевые моменты\nДержите штангу близко к центру тела\nНе скручивайте корпус во время подъема\nРаботайте с умеренным весом, пока не отработаете механику',

  [normalizeExerciseName('Snatch Grip Deadlift')]:
    'Техника выполнения\n1. Позиция\nВстаньте на ширине таза, возьмите штангу очень широким хватом.\n\n2. Исходное положение\nТаз чуть ниже, чем в классической тяге, грудная клетка раскрыта, спина ровная.\n\n3. Подъем\nОттолкнитесь ногами от пола и поднимайте штангу вверх, сохраняя ее близко к телу.\n\n4. Верхняя точка\nВыпрямитесь полностью, стабилизируйте корпус и лопатки.\n\n5. Опускание\nОпускайте штангу обратно через контролируемый тазовый наклон.\n\nКлючевые моменты\nШирокий хват увеличивает нагрузку на верх спины и заднюю цепь\nНе допускайте отрыва штанги от тела\nТехника важнее веса из-за повышенной амплитуды',

  [normalizeExerciseName('Lat Pulldown (close grip)')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажер, зафиксируйте бедра под валиками, возьмитесь узким хватом за рукоять.\n\n2. Исходное положение\nРуки полностью выпрямлены вверх, грудь раскрыта, корпус слегка отклонен назад.\n\n3. Тяга\nТяните рукоять к верхней части груди, ведя локти вниз вдоль корпуса.\n\n4. Пиковое сокращение\nВ нижней точке задержитесь на 1 секунду и сожмите широчайшие.\n\n5. Возврат\nМедленно верните рукоять вверх до полного растяжения мышц спины.\n\nКлючевые моменты\nНе тяните плечами к ушам\nУзкий хват сильнее включает нижние пучки широчайших\nБез раскачки корпуса и рывков',

  [normalizeExerciseName('Single-arm Lat Pulldown')]:
    'Техника выполнения\n1. Позиция\nУстановите одноручную рукоять на верхний блок и сядьте боком или лицом к тренажеру.\n\n2. Исходное положение\nРабочая рука вытянута вверх, плечо опущено, корпус стабилен.\n\n3. Тяга\nТяните рукоять вниз к верхней части груди, ведя локоть к тазу.\n\n4. Верхняя точка\nСделайте короткую паузу в сокращении широчайшей мышцы.\n\n5. Возврат\nПод контролем верните руку вверх до полного растяжения и повторите.\n\nКлючевые моменты\nОтлично выравнивает дисбаланс между правой и левой стороной\nНе разворачивайте корпус в сторону тяги\nКонтролируйте отрицательную фазу',

  [normalizeExerciseName('Pendlay Row')]:
    'Техника выполнения\n1. Позиция\nВстаньте над штангой, наклонитесь до почти параллели корпуса с полом.\n\n2. Исходное положение\nСпина нейтральна, штанга на полу перед каждым повтором.\n\n3. Тяга\nРезко, но технически чисто тяните штангу к нижней части груди.\n\n4. Контроль\nВверху коротко зафиксируйте лопатки и сразу опустите штангу обратно на пол.\n\n5. Повтор\nКаждое повторение начинается с полной остановки штанги на полу.\n\nКлючевые моменты\nНе округляйте поясницу\nТяга идет спиной и локтями, а не разгибанием корпуса\nОдинаковая стартовая позиция в каждом повторении обязательна',

  [normalizeExerciseName('Bent-Over Barbell Row')]:
    'Техника выполнения\n1. Позиция\nВстаньте, поставив стопы на ширину таза. Возьмите штангу хватом чуть шире плеч.\n\n2. Исходное положение\nНаклонитесь вперёд, отводя таз назад. Спина ровная, корпус стабилен, штанга находится под плечами. Колени слегка согнуты.\n\n3. Движение\nТяните штангу к нижней части рёбер, уводя локти назад. Держите штангу близко к телу.\n\n4. Верхняя точка\nПодведите штангу к корпусу, сведите лопатки и задержитесь на 1 секунду.\n\n5. Возврат\nМедленно опустите штангу вниз до полного выпрямления рук, сохраняя контроль.\n\n6. Дыхание\nВыдох при тяге, вдох при опускании.\n\nКлючевые моменты\nСохраняйте нейтральное положение спины, не округляйте поясницу\nУводите локти назад, а не вверх\nДержите штангу близко к телу на всей амплитуде\nБез инерции, весь подход подконтрольно',

  [normalizeExerciseName('Ring Rows')]:
    'Техника выполнения\n1. Позиция\nВозьмитесь за гимнастические кольца и отклонитесь назад, тело держите в прямой линии.\n\n2. Исходное положение\nРуки выпрямлены, корпус напряжен, стопы в устойчивой позиции.\n\n3. Тяга\nПодтягивайте грудь к кольцам, уводя локти назад и сводя лопатки.\n\n4. Верхняя точка\nЗадержитесь на 1 секунду в полном сведении лопаток.\n\n5. Возврат\nМедленно выпрямите руки и вернитесь в исходное положение.\n\nКлючевые моменты\nЧем ниже корпус к полу, тем выше сложность\nНе провисайте в тазу\nКольца требуют большего контроля стабилизаторов, чем фиксированная перекладина',

  [normalizeExerciseName('High Row (cable)')]:
    'Техника выполнения\n1. Позиция\nУстановите рукояти блока на уровне груди или выше и встаньте/сядьте в устойчивую позицию.\n\n2. Исходное положение\nРуки вытянуты вперед, грудная клетка раскрыта, плечи опущены.\n\n3. Тяга\nТяните рукояти к верхней части груди, разводя локти в стороны и назад.\n\n4. Пиковое сокращение\nВ конце тяги сведите лопатки и удержите 1 секунду.\n\n5. Возврат\nВерните рукояти вперед медленно, сохраняя контроль.\n\nКлючевые моменты\nАкцент на верх спины и заднюю дельту\nНе зажимайте шею и не поднимайте плечи\nКонтролируйте амплитуду без рывков',

  [normalizeExerciseName('Seal Row')]:
    'Техника выполнения\n1. Позиция\nЛягте грудью на высокую горизонтальную скамью, штанга или гантели под вами.\n\n2. Исходное положение\nРуки свободно свисают вниз, корпус полностью опирается на скамью.\n\n3. Тяга\nТяните вес к нижней части грудной клетки, уводя локти назад.\n\n4. Верхняя точка\nСведите лопатки и удержите сокращение 1 секунду.\n\n5. Возврат\nМедленно опустите вес до полного выпрямления рук.\n\nКлючевые моменты\nПолная опора корпусом почти исключает читинг\nОтлично нагружает середину спины\nНе бейте весом о скамью внизу амплитуды',

  [normalizeExerciseName('Alternating Biceps Curl')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, удерживая по отягощению в каждой руке вдоль корпуса.\n\n2. Исходное положение\nЛокти прижаты к корпусу, плечи опущены, корпус стабилен.\n\n3. Движение\nСгибайте поочередно одну руку к плечу, вторая остается неподвижной.\n\n4. Верхняя точка\nКоротко сожмите бицепс в пике движения.\n\n5. Возврат\nОпустите руку медленно и повторите другой стороной.\n\nКлючевые моменты\nНе раскачивайте корпус\nДержите локти прижатыми\nРаботайте в полной амплитуде',

  [normalizeExerciseName('Bench Crunches')]:
    'Техника выполнения\n1. Позиция\nЛягте на скамью с наклоном вниз, зафиксируйте ноги под валиками. Руки за головой или скрещены на груди.\n\n2. Исходное положение\nКорпус опущен назад, поясница слегка прижата к скамье. Шея в нейтральном положении.\n\n3. Движение\nСкручивайте корпус вверх за счёт напряжения мышц пресса. Поясница остаётся прижатой, движение происходит в грудном отделе.\n\n4. Верхняя точка\nПоднимитесь до максимального сокращения мышц пресса. Задержитесь на 1 секунду.\n\n5. Возврат\nМедленно опуститесь обратно, сохраняя контроль и не расслабляя пресс полностью.\n\n6. Дыхание\nВыдох при скручивании, вдох при опускании.\n\nКлючевые моменты\nНе тяните себя руками за голову — движение за счёт пресса\nНе прогибайтесь в пояснице, сохраняйте контроль\nВыполняйте движение плавно, без рывков\nЧем больше наклон, тем выше нагрузка 💪',

  [normalizeExerciseName('Bench Reverse Crunch')]:
    'Техника выполнения\n1. Позиция\nЛягте на скамью, возьмитесь руками за край над головой для фиксации.\n\n2. Исходное положение\nКолени согнуты под 90 градусов, поясница прижата к скамье.\n\n3. Движение\nПодкрутите таз и подтяните колени к груди, отрывая таз от скамьи.\n\n4. Верхняя точка\nСделайте короткую паузу и максимально напрягите нижний пресс.\n\n5. Возврат\nМедленно опустите таз и ноги в исходное положение.\n\nКлючевые моменты\nНе делайте махов ногами\nКонтролируйте каждое повторение\nФокус на подкручивании таза',

  [normalizeExerciseName('Bench/Chair Dips')]:
    'Техника выполнения\n1. Позиция\nСядьте на край стула или скамьи, ладони поставьте по бокам таза.\n\n2. Исходное положение\nСойдите тазом вперед, руки выпрямлены, ноги вытянуты или согнуты.\n\n3. Опускание\nСгибайте локти и опускайтесь вниз до угла около 90 градусов.\n\n4. Подъем\nРазогните локти и вернитесь в исходное положение.\n\n5. Контроль\nПовторяйте в ровном темпе без рывков.\n\nКлючевые моменты\nЛокти направлены назад, не в стороны\nНе опускайтесь слишком глубоко\nПлечи держите опущенными',

  [normalizeExerciseName('Bicycle Crunches')]:
    'Техника выполнения\n1. Позиция\nЛягте на спину, руки за головой, колени подняты.\n\n2. Исходное положение\nПлечи слегка оторваны от пола, пресс напряжен.\n\n3. Движение\nПодведите локоть к противоположному колену, вторую ногу выпрямите.\n\n4. Чередование\nПлавно смените сторону, сохраняя ритм.\n\n5. Завершение\nВыполняйте повторения подконтрольно до конца подхода.\n\nКлючевые моменты\nНе тяните шею руками\nРаботайте за счет скручивания корпуса\nДержите поясницу под контролем',

  [normalizeExerciseName('Burpees')]:
    'Техника выполнения\n1. Старт\nВстаньте прямо, стопы на ширине плеч.\n\n2. Спуск\nПрисядьте, поставьте ладони на пол и перейдите в упор лежа.\n\n3. Планка\nСтабилизируйте корпус, при необходимости выполните отжимание.\n\n4. Подъем\nПодтяните ноги к рукам и резко выпрямитесь с прыжком вверх.\n\n5. Повтор\nМягко приземлитесь и сразу переходите к следующему повторению.\n\nКлючевые моменты\nСледите за мягким приземлением\nНе округляйте поясницу при переходах\nТемп держите контролируемым',

  [normalizeExerciseName('Cat Plank / Knee-to-chest plank')]:
    'Техника выполнения\n1. Позиция\nПримите упор лежа, ладони под плечами.\n\n2. Исходное положение\nТело в прямой линии, пресс и ягодицы напряжены.\n\n3. Движение\nПодтяните одно колено к груди, сохраняя таз стабильным.\n\n4. Возврат\nВерните ногу назад и повторите другой стороной.\n\n5. Контроль\nДвигайтесь медленно, без раскачки корпуса.\n\nКлючевые моменты\nНе поднимайте таз слишком высоко\nПлечи не уводите к ушам\nСохраняйте ровное дыхание',

  [normalizeExerciseName('Crunches')]:
    'Техника выполнения\n1. Позиция\nЛягте на спину, колени согнуты, стопы на полу.\n\n2. Исходное положение\nРуки у висков или на груди, поясница прижата к полу.\n\n3. Подъем\nПоднимайте лопатки от пола за счет мышц пресса.\n\n4. Верхняя точка\nКоротко зафиксируйтесь и выдохните.\n\n5. Возврат\nМедленно опуститесь обратно без расслабления пресса.\n\nКлючевые моменты\nНе тяните голову руками\nАмплитуда небольшая, но подконтрольная\nНе бросайте корпус вниз',

  [normalizeExerciseName('Dead Bug')]:
    'Техника выполнения\n1. Позиция\nЛягте на спину, руки вверх, бедра и колени под 90 градусов.\n\n2. Исходное положение\nПоясница прижата к полу, корпус напряжен.\n\n3. Движение\nМедленно выпрямляйте одну ногу, сохраняя вторую в исходной позиции.\n\n4. Возврат\nВерните ногу назад и выполните повтор другой ногой.\n\n5. Контроль\nПоддерживайте стабильность таза и корпуса на каждом повторении.\n\nКлючевые моменты\nПоясница не должна отрываться от пола\nДвигайтесь медленно\nДышите ровно, без задержек',

  [normalizeExerciseName('Fast Plank Steps')]:
    'Техника выполнения\n1. Позиция\nВстаньте в планку с опорой на ладони или предплечья.\n\n2. Исходное положение\nКорпус в прямой линии, пресс напряжен.\n\n3. Движение\nБыстро переступайте ногами короткими шагами, сохраняя корпус неподвижным.\n\n4. Контроль\nНе допускайте раскачки таза и провала поясницы.\n\n5. Завершение\nСохраняйте технику до конца подхода.\n\nКлючевые моменты\nКачество движения важнее скорости\nПлечи над опорой\nДыхание ритмичное',

  [normalizeExerciseName('Good Mornings (Bodyweight/Band)')]:
    'Техника выполнения\n1. Позиция\nВстаньте на ширине плеч, руки за головой или резинка на верхней части спины.\n\n2. Исходное положение\nКолени слегка согнуты, спина нейтральная, корпус напряжен.\n\n3. Наклон\nОтведите таз назад и наклоните корпус вперед за счет тазобедренного сустава.\n\n4. Нижняя точка\nОпускайтесь до выраженного, но комфортного натяжения задней поверхности бедра.\n\n5. Подъем\nВыведите таз вперед и вернитесь в вертикаль.\n\nКлючевые моменты\nНе округляйте спину\nДвижение из тазобедренного сустава\nСохраняйте контроль по всей амплитуде',

  [normalizeExerciseName('Heel Touches')]:
    'Техника выполнения\n1. Позиция\nЛягте на спину, согните колени, руки вдоль корпуса.\n\n2. Исходное положение\nЛопатки слегка приподняты, пресс напряжен.\n\n3. Движение\nТянитесь правой рукой к правой пятке, затем левой к левой.\n\n4. Чередование\nСохраняйте равномерный темп и контроль.\n\n5. Завершение\nПродолжайте до заданного количества повторений.\n\nКлючевые моменты\nРабота идет боковыми мышцами пресса\nНе тяните шею\nНе раскачивайте таз',

  [normalizeExerciseName('High Knees')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, стопы на ширине таза.\n\n2. Старт\nНачните бег на месте, активно поднимая колени вверх.\n\n3. Движение\nРаботайте руками в такт движению ног.\n\n4. Контроль\nСохраняйте корпус собранным и мягкое приземление.\n\n5. Завершение\nДержите ритм до конца подхода.\n\nКлючевые моменты\nНе заваливайтесь назад\nПоднимайте колени активно\nДышите ритмично',

  [normalizeExerciseName('Hip Thrust (Chair/Sofa)')]:
    'Техника выполнения\n1. Позиция\nСядьте на пол, уприте верх спины в край стула или дивана.\n\n2. Исходное положение\nСтопы на полу на ширине таза, колени согнуты, корпус напряжен.\n\n3. Подъем\nПоднимайте таз вверх, отталкиваясь пятками.\n\n4. Верхняя точка\nСильно сожмите ягодицы и удержите 1-2 секунды.\n\n5. Возврат\nМедленно опустите таз вниз под контролем.\n\nКлючевые моменты\nНе переразгибайте поясницу\nПодкручивайте таз вверху\nФокус на ягодицах, а не на инерции',

  [normalizeExerciseName('Inchworms')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, стопы на ширине таза.\n\n2. Наклон\nНаклонитесь и поставьте ладони на пол перед собой.\n\n3. Выход в планку\nПереставляйте руки вперед до позиции планки.\n\n4. Возврат\nШагами подтяните стопы к рукам и снова выпрямитесь.\n\n5. Повтор\nВыполняйте движение плавно и подконтрольно.\n\nКлючевые моменты\nНе провисайте в пояснице в планке\nСохраняйте контроль в плечах\nНе делайте рывков при возврате',

  [normalizeExerciseName('Jump Squat')]:
    'Техника выполнения\n1. Позиция\nВстаньте на ширине плеч, корпус стабилен.\n\n2. Опускание\nВыполните присед до комфортной глубины.\n\n3. Прыжок\nРезко оттолкнитесь и выпрыгните вверх.\n\n4. Приземление\nМягко приземлитесь на полусогнутые ноги.\n\n5. Повтор\nСразу переходите в следующее повторение.\n\nКлючевые моменты\nПриземляйтесь мягко\nКолени не заваливайте внутрь\nКонтролируйте темп',

  [normalizeExerciseName('Jumping Jacks')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, стопы вместе, руки вдоль корпуса.\n\n2. Движение вверх\nПрыжком разведите ноги в стороны и поднимите руки над головой.\n\n3. Возврат\nПрыжком вернитесь в исходное положение.\n\n4. Ритм\nПовторяйте движение в стабильном темпе.\n\n5. Контроль\nДержите мягкое приземление и ровное дыхание.\n\nКлючевые моменты\nНе приземляйтесь на прямые колени\nСохраняйте корпус устойчивым\nСкорость подбирайте под технику',

  [normalizeExerciseName('Lunge Jumps')]:
    'Техника выполнения\n1. Позиция\nВстаньте в выпад: одна нога впереди, другая сзади.\n\n2. Опускание\nСогните обе ноги и подготовьтесь к прыжку.\n\n3. Прыжок\nВыпрыгните вверх и поменяйте ноги в воздухе.\n\n4. Приземление\nМягко приземлитесь в выпад на противоположную сторону.\n\n5. Повтор\nПродолжайте чередование в контролируемом ритме.\n\nКлючевые моменты\nДержите колени по линии носков\nПриземляйтесь мягко\nНе теряйте баланс корпуса',

  [normalizeExerciseName('Mountain Climbers')]:
    'Техника выполнения\n1. Позиция\nПримите упор лежа, ладони под плечами.\n\n2. Исходное положение\nТело в прямой линии, пресс напряжен.\n\n3. Движение\nПоочередно подтягивайте колени к груди в быстром темпе.\n\n4. Контроль\nСохраняйте таз стабильным и не проваливайте поясницу.\n\n5. Завершение\nДержите ритм до конца подхода.\n\nКлючевые моменты\nНе поднимайте таз слишком высоко\nРаботайте от кора, а не инерцией\nРовное дыхание обязательно',

  [normalizeExerciseName('Overhead Triceps Extension (Bottle/DB/Band)')]:
    'Техника выполнения\n1. Позиция\nВстаньте или сядьте ровно, удерживайте отягощение обеими руками за головой.\n\n2. Исходное положение\nЛокти направлены вверх и близко к голове, корпус стабилен.\n\n3. Разгибание\nВыпрямляйте руки вверх, разгибая локти.\n\n4. Верхняя точка\nСильно сожмите трицепс в полном разгибании.\n\n5. Возврат\nМедленно опустите отягощение назад за голову.\n\nКлючевые моменты\nЛокти не разводите в стороны\nНе прогибайтесь в пояснице\nКонтролируйте негативную фазу',

  [normalizeExerciseName('Plank')]:
    'Техника выполнения\n1. Позиция\nПримите планку на предплечьях или ладонях.\n\n2. Исходное положение\nТело в прямой линии от головы до пят, пресс и ягодицы напряжены.\n\n3. Удержание\nСохраняйте положение без провала в пояснице.\n\n4. Дыхание\nДышите ровно, не задерживая дыхание.\n\n5. Завершение\nЗавершайте подход при сохранении техники.\n\nКлючевые моменты\nНе поднимайте таз слишком высоко\nНе опускайте поясницу\nКачество важнее времени удержания',

  [normalizeExerciseName('Plank with steps')]:
    'Техника выполнения\n1. Позиция\nВстаньте в планку, корпус стабилен.\n\n2. Исходное положение\nПлечи над опорой, пресс напряжен.\n\n3. Движение\nСделайте шаг ногой в сторону и верните ее обратно.\n\n4. Чередование\nПовторите движение другой ногой.\n\n5. Контроль\nСохраняйте таз неподвижным на всем подходе.\n\nКлючевые моменты\nНе раскачивайте корпус\nРаботайте коротким контролируемым шагом\nСохраняйте ровный ритм',

  [normalizeExerciseName('Push-Ups')]:
    'Техника выполнения\n1. Позиция\nПоставьте руки чуть шире плеч, тело в прямой линии.\n\n2. Исходное положение\nПресс и ягодицы напряжены, плечи над ладонями.\n\n3. Опускание\nСгибайте локти и опускайте грудь к полу под контролем.\n\n4. Подъем\nОттолкнитесь ладонями и вернитесь вверх до полного разгибания рук.\n\n5. Повтор\nСохраняйте технику одинаковой в каждом повторении.\n\nКлючевые моменты\nЛокти примерно под 45 градусов к корпусу\nНе провисайте в пояснице\nПолная амплитуда каждого повторения',

  [normalizeExerciseName('Renegade Row')]:
    'Техника выполнения\n1. Позиция\nПримите упор лежа, удерживая отягощения в руках.\n\n2. Исходное положение\nСтопы шире таза, корпус стабилен, таз ровный.\n\n3. Тяга\nПодтяните одно отягощение к поясу, не разворачивая корпус.\n\n4. Возврат\nОпустите отягощение обратно и выполните повтор другой рукой.\n\n5. Контроль\nЧередуйте стороны в ровном темпе.\n\nКлючевые моменты\nНе вращайте таз\nДержите пресс напряженным\nРаботайте подконтрольно без рывков',

  [normalizeExerciseName('Resistance Band Curl single arm')]:
    'Техника выполнения\n1. Позиция\nВстаньте на резинку одной ногой и возьмите второй конец рабочей рукой.\n\n2. Исходное положение\nРука выпрямлена, локоть прижат к корпусу.\n\n3. Сгибание\nСогните руку в локте и поднимайте кисть к плечу.\n\n4. Верхняя точка\nКоротко сожмите бицепс в пике движения.\n\n5. Возврат\nМедленно разогните руку обратно.\n\nКлючевые моменты\nНе двигайте локтем вперед\nНе раскачивайте корпус\nКонтролируйте опускание',

  [normalizeExerciseName('Reverse Crunches')]:
    'Техника выполнения\n1. Позиция\nЛягте на спину, руки вдоль корпуса, колени согнуты.\n\n2. Исходное положение\nПоясница прижата к полу, пресс напряжен.\n\n3. Движение\nПодкрутите таз и подтяните колени к груди.\n\n4. Верхняя точка\nСделайте паузу и сожмите нижний пресс.\n\n5. Возврат\nМедленно вернитесь в исходное положение.\n\nКлючевые моменты\nНе делайте мах ногами\nДвигайтесь через подкручивание таза\nСохраняйте контроль поясницы',

  [normalizeExerciseName('Reverse Plank')]:
    'Техника выполнения\n1. Позиция\nСядьте на пол, ладони поставьте позади таза, ноги выпрямите.\n\n2. Исходное положение\nПлечи раскрыты, корпус собран.\n\n3. Подъем\nПоднимите таз вверх до прямой линии тела.\n\n4. Удержание\nСохраняйте положение и ровное дыхание.\n\n5. Возврат\nОпустите таз вниз под контролем.\n\nКлючевые моменты\nНе зажимайте плечи\nНе проваливайте таз\nФокус на ягодицах и задней цепи',

  [normalizeExerciseName('Scissors')]:
    'Техника выполнения\n1. Позиция\nЛягте на спину, ноги выпрямлены, руки вдоль корпуса.\n\n2. Исходное положение\nПоднимите ноги над полом, пресс напряжен.\n\n3. Движение\nПерекрещивайте ноги поочередно небольшими амплитудами.\n\n4. Контроль\nСохраняйте поясницу прижатой к полу.\n\n5. Завершение\nПоддерживайте темп до конца подхода.\n\nКлючевые моменты\nНе поднимайте голову рывками\nНе бросайте ноги вниз\nПлавное дыхание без задержек',

  [normalizeExerciseName('Seated Knee Tucks')]:
    'Техника выполнения\n1. Позиция\nСядьте на пол или скамью, слегка отклонитесь назад.\n\n2. Исходное положение\nНоги приподняты, корпус стабилен, руки для баланса у опоры.\n\n3. Движение\nПодтяните колени к груди, сокращая пресс.\n\n4. Возврат\nВыпрямите ноги вперед под контролем.\n\n5. Повтор\nВыполняйте в плавном ритме без инерции.\n\nКлючевые моменты\nНе округляйте поясницу чрезмерно\nФокус на работе пресса\nСохраняйте стабильность корпуса',

  [normalizeExerciseName('Side Crunches on Bench')]:
    'Техника выполнения\n1. Позиция\nСядьте боком на скамью, одна рука за головой, вторая держит опору.\n\n2. Исходное положение\nКорпус слегка наклонен в сторону растяжения.\n\n3. Движение\nСкручивайтесь в бок, приближая ребра к тазу.\n\n4. Возврат\nМедленно вернитесь в исходное положение.\n\n5. Смена стороны\nВыполните подход и повторите на другую сторону.\n\nКлючевые моменты\nНе скручивайте корпус вперед\nРаботайте за счет косых мышц\nДержите движение плавным',

  [normalizeExerciseName('Single Leg Raises')]:
    'Техника выполнения\n1. Позиция\nЛягте на спину, руки вдоль корпуса.\n\n2. Исходное положение\nОдна нога выпрямлена на полу, другая рабочая нога готова к подъему.\n\n3. Подъем\nПоднимайте рабочую ногу вверх под контролем.\n\n4. Опускание\nМедленно опускайте ногу обратно, не теряя напряжения пресса.\n\n5. Смена ноги\nВыполните нужное число повторений и смените сторону.\n\nКлючевые моменты\nПоясница остается прижатой к полу\nНе бросайте ногу вниз\nСохраняйте стабильность таза',

  [normalizeExerciseName('Skater Jumps')]:
    'Техника выполнения\n1. Позиция\nВстаньте на одну ногу, корпус слегка наклонен вперед.\n\n2. Прыжок\nВыполните боковой прыжок на другую ногу.\n\n3. Приземление\nМягко приземлитесь и стабилизируйте колено.\n\n4. Чередование\nПродолжайте прыжки из стороны в сторону.\n\n5. Контроль\nСохраняйте баланс и ровный ритм.\n\nКлючевые моменты\nНе заваливайте колено внутрь\nПриземляйтесь мягко\nДержите корпус под контролем',

  [normalizeExerciseName('Squat to Knee squat')]:
    'Техника выполнения\n1. Позиция\nВстаньте на ширине плеч, корпус стабилен.\n\n2. Присед\nВыполните контролируемый присед вниз.\n\n3. Подъем\nПоднимитесь вверх и сразу подтяните одно колено к груди.\n\n4. Чередование\nСледующий повтор выполните с подъемом другого колена.\n\n5. Ритм\nДвигайтесь плавно, сохраняя технику.\n\nКлючевые моменты\nНе заваливайте корпус назад при подъеме колена\nДержите опорную стопу полностью на полу\nНе ускоряйтесь в ущерб качеству',

  [normalizeExerciseName('Superman')]:
    'Техника выполнения\n1. Позиция\nЛягте на живот, руки вытянуты вперед, ноги прямые.\n\n2. Подъем\nОдновременно поднимите руки, грудь и ноги вверх.\n\n3. Верхняя точка\nСожмите ягодицы и мышцы спины, удержите 1 секунду.\n\n4. Возврат\nОпуститесь вниз медленно и подконтрольно.\n\n5. Повтор\nВыполняйте повторения без рывков.\n\nКлючевые моменты\nНе запрокидывайте шею\nДержите движение плавным\nФокус на задней цепи мышц',

  [normalizeExerciseName('Triceps Kickbacks')]:
    'Техника выполнения\n1. Позиция\nНаклонитесь вперед, опираясь одной рукой на опору, во второй руке отягощение.\n\n2. Исходное положение\nПлечо рабочей руки прижато к корпусу, локоть согнут под 90 градусов.\n\n3. Разгибание\nРазгибайте руку назад за счет локтя, не двигая плечо.\n\n4. Верхняя точка\nСожмите трицепс и сделайте короткую паузу.\n\n5. Возврат\nМедленно верните предплечье в исходное положение.\n\nКлючевые моменты\nПлечо остается неподвижным\nНе используйте инерцию\nКонтролируйте негативную фазу',

  [normalizeExerciseName('Tuck Jumps')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, стопы на ширине таза.\n\n2. Подготовка\nСлегка присядьте для набора импульса.\n\n3. Прыжок\nВыпрыгните вверх и подтяните колени к груди.\n\n4. Приземление\nМягко приземлитесь на полусогнутые ноги.\n\n5. Повтор\nСохраняйте контроль и ритм каждого повторения.\n\nКлючевые моменты\nПриземляйтесь тихо и мягко\nНе теряйте положение корпуса\nСкорость подчиняйте технике',

  [normalizeExerciseName('Wall Sit')]:
    'Техника выполнения\n1. Позиция\nПрислонитесь спиной к стене и сделайте шаг вперед.\n\n2. Опускание\nСкользите вниз до угла около 90 градусов в коленях.\n\n3. Удержание\nДержите положение, прижав спину к стене.\n\n4. Контроль\nРавномерно распределяйте вес на стопах.\n\n5. Завершение\nПо окончании подхода медленно поднимитесь вверх.\n\nКлючевые моменты\nКолени направлены по линии носков\nНе отрывайте поясницу от стены\nДышите ровно в удержании',

  [normalizeExerciseName('Wide Push-Ups')]:
    'Техника выполнения\n1. Позиция\nПоставьте руки шире плеч, тело в прямой линии.\n\n2. Исходное положение\nКорпус напряжен, плечи стабильны.\n\n3. Опускание\nСгибайте локти и опускайте грудь к полу под контролем.\n\n4. Подъем\nОттолкнитесь ладонями и вернитесь в верхнюю точку.\n\n5. Повтор\nСохраняйте одинаковую технику в каждом повторении.\n\nКлючевые моменты\nШирокий упор больше нагружает грудные мышцы\nНе проваливайте поясницу\nНе разводите локти слишком резко',

  [normalizeExerciseName('Barbell Squat')]:
    'Техника выполнения\n1. Позиция\nУстановите штангу на верхней части спины (трапеции), стопы на ширине плеч, носки слегка развернуты наружу.\n\n2. Исходное положение\nСнимите штангу со стоек, сделайте шаг назад, корпус напряжён, спина нейтральна, взгляд направлен вперёд.\n\n3. Опускание\nСгибайте колени и тазобедренные суставы одновременно, отводя таз назад и вниз. Колени направлены по линии носков.\n\n4. Нижняя точка\nОпускайтесь до контролируемой глубины (обычно до параллели бедра), сохраняя нейтральное положение спины.\n\n5. Подъём\nПоднимайтесь за счёт давления через пятки и середину стопы, сохраняя стабильный корпус и ровную траекторию.\n\nКлючевые моменты\nНе сводите колени внутрь\nНе теряйте нейтральное положение спины в нижней точке\nВес увеличивайте только при стабильной технике',

  [normalizeExerciseName('Smith Machine/burbell Squat')]:
    'Техника выполнения\n1. Позиция\nРасположитесь под грифом в тренажёре Смита или под штангой так, чтобы гриф лежал на верхней части спины. Стопы на ширине плеч.\n\n2. Исходное положение\nСнимите гриф со стопоров (в Смите — поворотом кистей), корпус напряжён, грудная клетка раскрыта.\n\n3. Опускание\nОпускайтесь, одновременно сгибая колени и тазобедренные суставы. Колени направлены по линии носков.\n\n4. Нижняя точка\nОпуститесь до контролируемой глубины (до параллели бедра или ниже при сохранении техники).\n\n5. Подъём\nПоднимайтесь вверх за счёт давления через стопы, сохраняя контроль и нейтральное положение корпуса.\n\nКлючевые моменты\nВ Смите удерживайте ровную траекторию грифа без рывков\nНе переносите вес на носки — опора через середину стопы и пятки\nСначала качество движения, затем увеличение нагрузки',

  [normalizeExerciseName('Hack Squat')]:
    'Техника выполнения\n1. Позиция\nВстаньте в гакк-тренажёр: спина плотно прижата к опоре, плечи под упорами, стопы на платформе на ширине плеч.\n\n2. Исходное положение\nСнимите стопоры, корпус напряжён, грудная клетка раскрыта, носки слегка развернуты наружу.\n\n3. Опускание\nСгибайте колени и тазобедренные суставы одновременно, опуская каретку под контролем. Колени направлены по линии носков.\n\n4. Нижняя точка\nОпуститесь до контролируемой глубины (обычно до параллели бедра), сохраняя опору на середину стопы и пятки.\n\n5. Подъём\nВыжимайте платформу вверх, сохраняя ровный темп и стабильное положение корпуса.\n\nКлючевые моменты\nНе сводите колени внутрь на подъёме\nНе отрывайте поясницу и таз от спинки тренажёра\nКонтролируйте негативную фазу — не падайте вниз',

  [normalizeExerciseName('Hack RDL')]:
    'Техника выполнения\n1. Позиция\nВстаньте на платформу гакк-тренажёра лицом к опоре (обратная стойка), плечи под упорами, стопы на ширине плеч.\n\n2. Исходное положение\nСнимите стопоры, спина нейтральная, корпус напряжён, колени слегка согнуты и фиксированы в этом угле.\n\n3. Наклон\nОтводите таз назад и опускайтесь за счёт тазобедренного сгибания, сохраняя спину ровной.\n\n4. Нижняя точка\nОпускайтесь до выраженного натяжения задней поверхности бедра, без округления спины.\n\n5. Возврат\nВыведите таз вперёд и вернитесь в исходное положение, сохраняя контроль по всей амплитуде.\n\nКлючевые моменты\nЭто движение «тазом назад», а не присед\nКаретка движется по направляющим — темп должен быть плавным, без рывков\nФокус на ягодицах и задней поверхности бедра, а не на пояснице',

  [normalizeExerciseName('Barbell Hip Thrust')]:
    'Техника выполнения\n1. Позиция\nСядьте на пол, упритесь верхом спины в край скамьи и расположите штангу в сгибе бедра (используйте мягкую накладку на гриф для комфорта).\n\n2. Исходное положение\nЛопатки опираются на скамью, колени согнуты, стопы на полу на ширине таза. Корпус напряжён, взгляд вперёд.\n\n3. Подъём\nОттолкнитесь пятками и поднимайте таз вверх до линии «плечи-таз-колени».\n\n4. Верхняя точка\nСильно сожмите ягодицы и удержите 1-2 секунды, сохраняя лёгкий подбородок вниз.\n\n5. Опускание\nМедленно опустите таз вниз под контролем, не теряя напряжения в ягодицах.\n\nКлючевые моменты\nВ верхней точке не переразгибайте поясницу — движение из ягодиц\nОпора через середину стопы и пятки\nСначала качественное сокращение ягодиц, затем увеличение веса',

  [normalizeExerciseName('Machine Hip Thrust')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажёр для ягодичного моста и отрегулируйте положение спинки и стоп под себя. Зафиксируйте тазовый валик.\n\n2. Исходное положение\nСтопы полностью на платформе, лопатки упираются в спинку, валик расположен в сгибе бедра. Корпус напряжён.\n\n3. Подъём\nОттолкнитесь пятками и поднимайте таз вверх до линии «плечи-таз-колени».\n\n4. Верхняя точка\nСильно сожмите ягодицы и удержите 1-2 секунды. Подбородок слегка опущен, рёбра под контролем.\n\n5. Опускание\nПлавно опустите таз в исходное положение, сохраняя контроль и напряжение в ягодицах.\n\nКлючевые моменты\nТренажёр даёт стабильную траекторию, поэтому фокус на качестве сокращения\nНе переразгибайте поясницу в верхней точке\nДавление через середину стопы и пятки, не через носки',

  [normalizeExerciseName('Hip Thrust Machine')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажёр для ягодичного моста и отрегулируйте положение спинки и стоп под себя. Зафиксируйте тазовый валик.\n\n2. Исходное положение\nСтопы полностью на платформе, лопатки упираются в спинку, валик расположен в сгибе бедра. Корпус напряжён.\n\n3. Подъём\nОттолкнитесь пятками и поднимайте таз вверх до линии «плечи-таз-колени».\n\n4. Верхняя точка\nСильно сожмите ягодицы и удержите 1-2 секунды. Подбородок слегка опущен, рёбра под контролем.\n\n5. Опускание\nПлавно опустите таз в исходное положение, сохраняя контроль и напряжение в ягодицах.\n\nКлючевые моменты\nТренажёр даёт стабильную траекторию, поэтому фокус на качестве сокращения\nНе переразгибайте поясницу в верхней точке\nДавление через середину стопы и пятки, не через носки',

  [normalizeExerciseName('Bridge Machine')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажёр для ягодичного моста и отрегулируйте положение спинки и стоп под себя. Зафиксируйте тазовый валик.\n\n2. Исходное положение\nСтопы полностью на платформе, лопатки упираются в спинку, валик расположен в сгибе бедра. Корпус напряжён.\n\n3. Подъём\nОттолкнитесь пятками и поднимайте таз вверх до линии «плечи-таз-колени».\n\n4. Верхняя точка\nСильно сожмите ягодицы и удержите 1-2 секунды. Подбородок слегка опущен, рёбра под контролем.\n\n5. Опускание\nПлавно опустите таз в исходное положение, сохраняя контроль и напряжение в ягодицах.\n\nКлючевые моменты\nТренажёр даёт стабильную траекторию, поэтому фокус на качестве сокращения\nНе переразгибайте поясницу в верхней точке\nДавление через середину стопы и пятки, не через носки',

  [normalizeExerciseName('Hip Thrust / Glute Bridge')]:
    'Техника выполнения\n1. Позиция\nРасположитесь так, чтобы верх спины опирался на скамью (или на пол для моста), стопы на ширине таза.\n\n2. Исходное положение\nКолени согнуты, корпус стабилен, ягодицы и пресс в лёгком напряжении.\n\n3. Подъём\nПоднимайте таз вверх за счёт давления пятками в пол, сохраняя контроль корпуса.\n\n4. Верхняя точка\nСожмите ягодицы максимально и удержите 1-2 секунды без прогиба в пояснице.\n\n5. Опускание\nПлавно опустите таз вниз и сразу переходите к следующему повторению без потери техники.\n\nКлючевые моменты\nНе бросайте таз вниз — контролируйте негативную фазу\nКолени направлены по линии носков\nГлавный фокус — работа ягодиц, а не амплитуда любой ценой',

  [normalizeExerciseName('Lat Pulldown (wide grip)')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажёр, зафиксируйте бёдра под валиками и возьмитесь за гриф широким хватом.\n\n2. Исходное положение\nРуки выпрямлены вверх, грудная клетка раскрыта, плечи опущены.\n\n3. Тяга\nТяните гриф к верхней части груди, ведя локти вниз и в стороны.\n\n4. Нижняя точка\nСведите лопатки и задержитесь на 1 секунду.\n\n5. Возврат\nПлавно верните гриф вверх до полного растяжения широчайших мышц.\n\nКлючевые моменты\nНе тяните гриф за счёт раскачки корпуса\nДержите плечи опущенными, не зажимайте шею\nКонтролируйте негативную фазу',

  [normalizeExerciseName('Pec Deck Machine')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажёр, прижмите спину к спинке, локти и предплечья установите на подушки/рукояти.\n\n2. Исходное положение\nРуки разведены, грудные мышцы в натяжении, корпус стабилен.\n\n3. Сведение\nСводите руки перед собой по дуге, акцентируя работу грудных мышц.\n\n4. Пиковое сокращение\nВ конечной точке сделайте паузу 1 секунду и сожмите грудные мышцы.\n\n5. Возврат\nМедленно разведите руки обратно под контролем, не бросая вес.\n\nКлючевые моменты\nНе выталкивайте движение плечами\nСохраняйте фиксированный угол в локтях\nРаботайте в комфортной амплитуде без боли в плечах',

  [normalizeExerciseName('Dumbbell Biceps Curl')]:
    'Техника выполнения\n1. Позиция\nВстаньте ровно, удерживая гантели вдоль корпуса, ладони направлены вперёд.\n\n2. Исходное положение\nЛокти прижаты к корпусу, плечи опущены, корпус стабилен.\n\n3. Сгибание\nПоднимайте гантели к плечам за счёт сгибания локтей, без движения плечами.\n\n4. Верхняя точка\nСожмите бицепс и удержите 1 секунду.\n\n5. Возврат\nПлавно опустите гантели до полного разгибания рук.\n\nКлючевые моменты\nНе раскачивайте корпус\nЛокти остаются рядом с корпусом\nКонтролируйте как подъём, так и опускание',

  [normalizeExerciseName('Triceps Pushdown (Cable)')]:
    'Техника выполнения\n1. Позиция\nВстаньте у верхнего блока, возьмите рукоять прямым хватом.\n\n2. Исходное положение\nЛокти прижаты к корпусу, предплечья направлены вперёд, корпус слегка наклонён.\n\n3. Разгибание\nРазгибайте руки вниз за счёт трицепса, не двигая плечами.\n\n4. Нижняя точка\nПолностью выпрямите руки и сделайте короткую паузу.\n\n5. Возврат\nМедленно верните рукоять в исходное положение под контролем.\n\nКлючевые моменты\nЛокти неподвижны на протяжении всего подхода\nНе помогайте себе корпусом\nСохраняйте постоянное натяжение трицепса',

  [normalizeExerciseName('Leg Press')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажёр жима ногами, прижмите спину к опоре, стопы на платформе на ширине плеч.\n\n2. Исходное положение\nСнимите стопоры, ноги почти выпрямлены, но колени не заблокированы.\n\n3. Опускание\nСгибайте колени и опускайте платформу под контролем до комфортной глубины.\n\n4. Нижняя точка\nСохраняйте поясницу прижатой к спинке, колени направлены по линии носков.\n\n5. Жим\nВыжимайте платформу вверх через пятки и середину стопы, не выпрямляя колени до жёсткого замка.\n\nКлючевые моменты\nНе отрывайте таз и поясницу от спинки\nНе сводите колени внутрь\nКонтролируйте темп, особенно в негативной фазе',

  [normalizeExerciseName('T-Bar Row')]:
    'Техника выполнения\n1. Позиция\nВстаньте к Т-грифу, стопы на ширине плеч, корпус в наклоне, спина нейтральна.\n\n2. Исходное положение\nВозьмитесь за рукоять, руки выпрямлены, корпус стабилен.\n\n3. Тяга\nТяните рукоять к нижней части груди/животу, ведя локти назад.\n\n4. Верхняя точка\nСведите лопатки и задержитесь на 1 секунду.\n\n5. Возврат\nПлавно опустите вес вниз до полного разгибания рук.\n\nКлючевые моменты\nНе округляйте спину\nНе раскачивайте корпус\nТяните локтями, а не только руками',

  [normalizeExerciseName('Face Pull')]:
    'Техника выполнения\n1. Позиция\nУстановите канат на верхний блок на уровне лица.\n\n2. Исходное положение\nВозьмитесь за канат, руки выпрямлены вперёд, локти слегка согнуты, корпус стабилен.\n\n3. Тяга\nТяните канат к лицу, разводя концы в стороны и уводя локти назад.\n\n4. Верхняя точка\nВ конце движения руки рядом с ушами, лопатки сведены. Задержитесь на 1 секунду.\n\n5. Возврат\nПлавно верните канат в исходное положение под контролем.\n\nКлючевые моменты\nДержите локти высоко\nНе поднимайте плечи к ушам\nФокус на задней дельте и верхней части спины',

  [normalizeExerciseName('Face Pulls')]:
    'Техника выполнения\n1. Позиция\nУстановите канат на верхний блок на уровне лица.\n\n2. Исходное положение\nВозьмитесь за канат, руки выпрямлены вперёд, локти слегка согнуты, корпус стабилен.\n\n3. Тяга\nТяните канат к лицу, разводя концы в стороны и уводя локти назад.\n\n4. Верхняя точка\nВ конце движения руки рядом с ушами, лопатки сведены. Задержитесь на 1 секунду.\n\n5. Возврат\nПлавно верните канат в исходное положение под контролем.\n\nКлючевые моменты\nДержите локти высоко\nНе поднимайте плечи к ушам\nФокус на задней дельте и верхней части спины',

  [normalizeExerciseName('Lying Leg Curls')]:
    'Техника выполнения\n1. Позиция\nЛягте в тренажёр для сгибания ног лёжа, валик расположен чуть выше лодыжек.\n\n2. Исходное положение\nНоги выпрямлены, таз и корпус прижаты к скамье, руки на рукоятях.\n\n3. Сгибание\nСгибайте ноги в коленях, подтягивая пятки к ягодицам.\n\n4. Верхняя точка\nСожмите заднюю поверхность бедра и удержите 1 секунду.\n\n5. Возврат\nМедленно разогните ноги в исходное положение, не бросая вес.\n\nКлючевые моменты\nТаз остаётся прижатым к скамье\nИзбегайте рывков\nКонтролируйте каждое повторение',

  [normalizeExerciseName('Seated Leg Curls')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажёр для сгибания ног сидя, отрегулируйте спинку и валик под рост.\n\n2. Исходное положение\nНоги почти выпрямлены, валик над лодыжками, корпус прижат к спинке.\n\n3. Сгибание\nСгибайте ноги в коленях, подтягивая валик назад под контролем.\n\n4. Верхняя точка\nСожмите заднюю поверхность бедра и задержитесь на 1 секунду.\n\n5. Возврат\nПлавно верните ноги в исходное положение, не теряя контроль.\n\nКлючевые моменты\nНе отрывайте таз от сиденья\nНе ускоряйте негативную фазу\nРаботайте в полной контролируемой амплитуде',

  [normalizeExerciseName('Seated Hip Abduction')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажёр отведения бедра, внешняя часть бедер упирается в подушки.\n\n2. Исходное положение\nКорпус прижат к спинке, стопы в опоре, колени сведены в стартовую позицию.\n\n3. Разведение\nРазводите бедра в стороны плавно, без рывков и раскачки корпуса.\n\n4. Пиковое сокращение\nВ крайней точке задержитесь на 1 секунду и сожмите ягодицы.\n\n5. Возврат\nМедленно верните бедра в исходное положение под контролем.\n\nКлючевые моменты\nДвижение идёт из тазобедренного сустава\nНе помогайте корпусом\nСохраняйте постоянное напряжение в ягодицах',

  [normalizeExerciseName('Back Extensions (Hyperextensions)')]:
    'Техника выполнения\n1. Позиция\nРасположитесь в тренажёре для гиперэкстензии так, чтобы подушка была на уровне верхней части бедра. Стопы зафиксированы.\n\n2. Исходное положение\nКорпус в нейтральном положении, руки на груди или за головой, спина ровная.\n\n3. Опускание\nПлавно наклоняйтесь вниз за счёт сгибания в тазобедренном суставе, сохраняя нейтральную спину.\n\n4. Подъём\nПоднимайтесь до прямой линии корпуса, напрягая ягодицы и разгибатели спины.\n\n5. Возврат\nПовторяйте в контролируемом темпе без рывков.\n\nКлючевые моменты\nНе переразгибайте поясницу в верхней точке\nНе округляйте спину внизу\nФокус на плавном контроле, а не на инерции',

  [normalizeExerciseName('Barbell Bench Press')]:
    'Техника выполнения\n1. Позиция\nЛягте на горизонтальную скамью, глаза под грифом. Возьмитесь за штангу хватом чуть шире плеч.\n\n2. Исходное положение\nСведите лопатки, слегка прогните грудной отдел, стопы плотно на полу. Снимите штангу со стоек.\n\n3. Опускание\nОпускайте штангу к нижней/средней части груди под контролем, локти под углом около 45-60 градусов к корпусу.\n\n4. Жим\nВыжимайте штангу вверх по естественной дуге до почти полного выпрямления рук.\n\n5. Возврат\nПосле подхода верните штангу на стойки под полным контролем.\n\nКлючевые моменты\nЛопатки сведены и стабилизированы весь подход\nНе отбивайте штангу от груди\nЗапястья держите над предплечьями без залома',

  [normalizeExerciseName('Dumbbell Bench Press')]:
    'Техника выполнения\n1. Позиция\nЛягте на горизонтальную скамью, гантели у груди, стопы устойчиво на полу.\n\n2. Исходное положение\nЛопатки сведены, плечи опущены, запястья нейтральны.\n\n3. Опускание\nОпускайте гантели по дуге до комфортной глубины, локти направлены вниз и немного в стороны.\n\n4. Жим\nВыжимайте гантели вверх, сохраняя контроль и симметрию движения обеих рук.\n\n5. Возврат\nМедленно переходите к следующему повторению без потери натяжения.\n\nКлючевые моменты\nНе сводите гантели ударом вверху\nСохраняйте одинаковую амплитуду обеими руками\nНе поднимайте плечи к ушам',

  [normalizeExerciseName('Incline Barbell Bench Press')]:
    'Техника выполнения\n1. Позиция\nУстановите скамью под наклоном 20-35 градусов. Лягте, возьмитесь за гриф хватом чуть шире плеч.\n\n2. Исходное положение\nСведите лопатки, стопы в опоре, штанга над верхней частью груди.\n\n3. Опускание\nОпускайте гриф к верхней части груди под контролем.\n\n4. Жим\nВыжимайте штангу вверх и слегка назад по стабильной траектории.\n\n5. Возврат\nПовторяйте движение в ровном темпе, сохраняя контроль плеч.\n\nКлючевые моменты\nУгол наклона умеренный: слишком высокий смещает акцент в переднюю дельту\nЛокти не разводите строго в стороны\nНе теряйте сведение лопаток внизу',

  [normalizeExerciseName('Incline Dumbbell Bench Press')]:
    'Техника выполнения\n1. Позиция\nСядьте на наклонную скамью (20-35 градусов) и выведите гантели в старт над верхом груди.\n\n2. Исходное положение\nЛопатки сведены, грудь раскрыта, стопы в устойчивой опоре.\n\n3. Опускание\nОпускайте гантели по дуге до комфортной глубины, сохраняя контроль плечевого сустава.\n\n4. Жим\nВыжимайте гантели вверх, сохраняя одинаковую скорость и амплитуду обеих рук.\n\n5. Возврат\nНе расслабляйте плечи внизу, переходите к следующему повторению плавно.\n\nКлючевые моменты\nКонтролируйте нижнюю фазу медленнее подъёма\nНе сталкивайте гантели в верхней точке\nСохраняйте нейтральные запястья',

  [normalizeExerciseName('Decline Barbell Bench Press')]:
    'Техника выполнения\n1. Позиция\nЛягте на скамью с отрицательным уклоном, зафиксируйте ноги. Возьмитесь за штангу хватом чуть шире плеч.\n\n2. Исходное положение\nСнимите штангу со стоек и удерживайте её над грудью. Руки выпрямлены, корпус стабилен.\n\n3. Движение\nМедленно опускайте штангу к нижней части груди, сгибая руки в локтях.\n\n4. Нижняя точка\nШтанга касается или находится близко к нижней части груди. Локти направлены под углом около 45°.\n\n5. Возврат\nВыжмите штангу вверх, возвращаясь в исходное положение.\n\n6. Дыхание\nВыдох при жиме, вдох при опускании.\n\nКлючевые моменты\nОсновная нагрузка смещается на нижнюю часть грудных мышц\nНе разводите локти слишком широко\nСохраняйте контроль, не отбивайте штангу от груди\nРаботайте в полной амплитуде без потери техники',

  [normalizeExerciseName('Decline Dumbbell Bench Press')]:
    'Техника выполнения\n1. Позиция\nЛягте на скамью с отрицательным уклоном, зафиксируйте ноги. Возьмите гантели и держите их на уровне груди.\n\n2. Исходное положение\nРуки согнуты, гантели находятся по бокам от груди. Корпус стабилен.\n\n3. Движение\nВыжимайте гантели вверх, сводя их по дуге над грудью.\n\n4. Верхняя точка\nГантели находятся над грудью, руки почти выпрямлены. Слегка сведите гантели и почувствуйте сокращение грудных мышц.\n\n5. Возврат\nМедленно опустите гантели обратно к груди, контролируя движение.\n\n6. Дыхание\nВыдох при жиме, вдох при опускании.\n\nКлючевые моменты\nГантели дают большую амплитуду и растяжение грудных мышц\nДвижение по дуге, а не строго вверх-вниз\nНе опускайте гантели слишком низко, если теряется контроль\nСохраняйте стабильность корпуса на протяжении всего упражнения',

  [normalizeExerciseName('Incline Dumbbell Fly')]:
    'Техника выполнения\n1. Позиция\nЛягте на наклонную скамью, гантели над грудью, локти слегка согнуты и зафиксированы.\n\n2. Исходное положение\nЛопатки сведены, грудь раскрыта, корпус стабилен.\n\n3. Разведение\nРазводите руки по широкой дуге до растяжения грудных мышц.\n\n4. Сведение\nСводите гантели обратно по той же дуге, концентрируясь на сокращении груди.\n\n5. Возврат\nДержите темп плавным, без рывков и перерастяжения внизу.\n\nКлючевые моменты\nУгол в локте почти не меняется\nНе опускайте гантели слишком глубоко при дискомфорте в плечах\nСводите за счёт груди, а не инерции',

  [normalizeExerciseName('Incline Cable Fly')]:
    'Техника выполнения\n1. Позиция\nУстановите блоки в нижнее положение и встаньте между стойками в разножку.\n\n2. Исходное положение\nРуки чуть согнуты, ладони смотрят друг на друга, грудь раскрыта.\n\n3. Сведение\nСводите руки вверх-вперёд по дуге до уровня верхней части груди.\n\n4. Пиковое сокращение\nЗадержитесь на 1 секунду в точке максимального сведения.\n\n5. Возврат\nМедленно разведите руки обратно, сохраняя натяжение тросов.\n\nКлючевые моменты\nНе разгибайте и не сгибайте локти во время повторения\nНе разворачивайте корпус вслед за руками\nПостоянно держите плечи опущенными',

  [normalizeExerciseName('Decline Cable Fly')]:
    'Техника выполнения\n1. Позиция\nУстановите блоки в верхнее положение и встаньте между стойками в устойчивую стойку.\n\n2. Исходное положение\nРуки слегка согнуты, ладони смотрят внутрь, корпус стабилен.\n\n3. Сведение\nВедите рукояти вниз-вперёд по дуге к нижней части груди/верху живота.\n\n4. Пиковое сокращение\nСожмите грудные мышцы внизу и удержите 1 секунду.\n\n5. Возврат\nПод контролем верните руки в исходное положение, не бросая вес.\n\nКлючевые моменты\nНе сутультесь в нижней точке\nСохраняйте небольшой фиксированный угол в локтях\nКонтроль в негативной фазе обязателен',

  [normalizeExerciseName('Barbell Overhead Press')]:
    'Техника выполнения\n1. Позиция\nВстаньте ровно, штанга на верхней части груди, хват немного шире плеч.\n\n2. Исходное положение\nПресс и ягодицы напряжены, локти слегка впереди грифа, запястья нейтральны.\n\n3. Жим\nВыжимайте штангу вверх по вертикальной траектории, уводя голову немного назад при старте.\n\n4. Верхняя точка\nЗафиксируйте штангу над серединой стопы, руки почти полностью выпрямлены.\n\n5. Опускание\nПлавно опустите штангу обратно к верхней части груди.\n\nКлючевые моменты\nНе переразгибайте поясницу\nГриф идёт близко к лицу, а не по дуге далеко вперёд\nСохраняйте напряжение кора на всём подходе',

  [normalizeExerciseName('Chin-ups')]:
    'Техника выполнения\n1. Позиция\nВозьмитесь за перекладину обратным хватом примерно на ширине плеч.\n\n2. Исходное положение\nПовисните на прямых руках, плечи опущены, корпус напряжён.\n\n3. Подтягивание\nТяните тело вверх, ведя локти вниз и назад.\n\n4. Верхняя точка\nПодбородок выше перекладины, короткая пауза и сжатие широчайших.\n\n5. Опускание\nОпускайтесь подконтрольно до полного разгибания рук.\n\nКлючевые моменты\nНе раскачивайте корпус\nНе поджимайте плечи к ушам\nПолная амплитуда важнее количества повторений',

  [normalizeExerciseName('Pull-ups')]:
    'Техника выполнения\n1. Позиция\nВозьмитесь за перекладину прямым хватом чуть шире плеч.\n\n2. Исходное положение\nВис на прямых руках, лопатки слегка опущены и активны, корпус стабилен.\n\n3. Подтягивание\nПодтягивайтесь вверх, ведя локти вниз к корпусу.\n\n4. Верхняя точка\nПодбородок выше перекладины, короткая фиксация без рывка.\n\n5. Опускание\nПлавно опускайтесь до полного выпрямления рук.\n\nКлючевые моменты\nИзбегайте маха ногами и рывков\nСохраняйте нейтральное положение шеи\nКонтролируйте темп на опускании',

  [normalizeExerciseName('Close-Grip Pull-Ups')]:
    'Задействованные мышцы\n\nШирочайшие мышцы спины, бицепс, средняя часть спины, предплечья\n\nТехника выполнения\n1. Позиция\nВозьмитесь за перекладину узким хватом (уже ширины плеч), ладони направлены от себя или нейтрально.\n\n2. Исходное положение\nПовисните на перекладине, руки полностью выпрямлены. Корпус стабилен, плечи опущены.\n\n3. Движение\nТяните тело вверх, уводя локти вниз и назад.\n\n4. Верхняя точка\nПодтянитесь до уровня, при котором подбородок находится выше перекладины. Сведите лопатки и удерживайте 1 секунду.\n\n5. Возврат\nМедленно опуститесь вниз до полного выпрямления рук.\n\n6. Дыхание\nВыдох при подтягивании, вдох при опускании.\n\nКлючевые моменты\nУзкий хват сильнее включает бицепс и нижнюю часть широчайших\nНе раскачивайтесь — движение под контролем\nОпускайтесь полностью для полной амплитуды\nДержите плечи опущенными, не тянитесь к ушам 💪',

  [normalizeExerciseName('Neutral-Grip Pull-Ups')]:
    'Задействованные мышцы\n\nШирочайшие мышцы спины, бицепс, средняя часть спины, предплечья\n\nТехника выполнения\n1. Позиция\nВозьмитесь за параллельные рукояти (ладони смотрят друг на друга).\n\n2. Исходное положение\nПовисните на перекладине, руки полностью выпрямлены. Корпус стабилен, плечи опущены.\n\n3. Движение\nТяните тело вверх, уводя локти вниз и назад.\n\n4. Верхняя точка\nПодтянитесь до уровня, при котором подбородок находится выше рукоятей. Сведите лопатки и удерживайте 1 секунду.\n\n5. Возврат\nМедленно опуститесь вниз до полного выпрямления рук.\n\n6. Дыхание\nВыдох при подтягивании, вдох при опускании.\n\nКлючевые моменты\nПараллельный хват более комфортен для плеч и запястий\nХороший баланс между работой спины и рук\nДержите движение под контролем, без раскачки\nПолная амплитуда — ключ к эффективности 💪',

  [normalizeExerciseName('Lat Pulldown')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажёр, зафиксируйте бёдра под валиками, возьмитесь за гриф удобным хватом.\n\n2. Исходное положение\nРуки выпрямлены вверх, грудь раскрыта, плечи опущены.\n\n3. Тяга\nТяните гриф к верхней части груди, направляя локти вниз.\n\n4. Нижняя точка\nСведите лопатки и удержите сокращение 1 секунду.\n\n5. Возврат\nМедленно верните гриф вверх до полного растяжения спины.\n\nКлючевые моменты\nНе тяните гриф за счёт раскачки\nДержите плечи опущенными\nНе отклоняйтесь сильно назад',

  [normalizeExerciseName('Seated Cable Row')]:
    'Техника выполнения\n1. Позиция\nСядьте к нижнему блоку, стопы в упорах, колени слегка согнуты.\n\n2. Исходное положение\nРуки выпрямлены, спина нейтральна, грудь раскрыта.\n\n3. Тяга\nТяните рукоять к нижним рёбрам/животу, уводя локти назад.\n\n4. Пиковое сокращение\nСведите лопатки и задержитесь на 1 секунду.\n\n5. Возврат\nПод контролем верните рукоять вперёд, сохраняя нейтральную спину.\n\nКлючевые моменты\nНе округляйте поясницу\nНе дёргайте корпусом назад\nКонтролируйте полную амплитуду',

  [normalizeExerciseName('Seated Cable Row (V-bar)')]:
    'Техника выполнения\n1. Позиция\nСядьте к нижнему блоку с V-рукоятью, стопы в упорах, корпус стабилен.\n\n2. Исходное положение\nСпина ровная, руки выпрямлены, плечи опущены.\n\n3. Тяга\nТяните V-рукоять к нижней части живота, ведя локти вдоль корпуса.\n\n4. Пиковое сокращение\nСведите лопатки и удержите 1 секунду.\n\n5. Возврат\nМедленно выпрямите руки, сохраняя натяжение в спине.\n\nКлючевые моменты\nНе откидывайтесь корпусом назад\nДержите запястья нейтрально\nНе теряйте контроль внизу',

  [normalizeExerciseName('Seated Cable Row (wide grip)')]:
    'Техника выполнения\n1. Позиция\nСядьте к блоку с широкой рукоятью, стопы в упорах, грудь раскрыта.\n\n2. Исходное положение\nРуки вытянуты вперёд, спина нейтральна, плечи опущены.\n\n3. Тяга\nТяните рукоять к верхней части живота/низу груди, разводя локти в стороны.\n\n4. Пиковое сокращение\nСведите лопатки и удержите 1 секунду.\n\n5. Возврат\nПлавно верните рукоять вперёд до полного растяжения мышц спины.\n\nКлючевые моменты\nНе тяните плечами к ушам\nНе округляйте грудной отдел\nКонтролируйте каждое повторение',

  [normalizeExerciseName('Chest Press Machine')]:
    'Техника выполнения\n1. Позиция\nОтрегулируйте сиденье так, чтобы рукояти были на уровне середины груди.\n\n2. Исходное положение\nСпина прижата к спинке, стопы на полу, лопатки сведены.\n\n3. Жим\nВыжимайте рукояти вперёд до почти полного выпрямления рук.\n\n4. Верхняя точка\nКоротко сожмите грудные мышцы без подъёма плеч.\n\n5. Возврат\nМедленно верните рукояти назад до комфортного растяжения грудных мышц.\n\nКлючевые моменты\nНе отрывайте поясницу от спинки\nНе блокируйте локти жёстко вверху\nКонтролируйте темп в обе стороны',

  [normalizeExerciseName('Seated Chest Press')]:
    'Техника выполнения\n1. Позиция\nСядьте в тренажёр жима от груди, выставьте сиденье под свой рост.\n\n2. Исходное положение\nРукояти на уровне груди, спина в опоре, корпус стабилен.\n\n3. Жим\nВыжимайте рукояти вперёд по заданной траектории.\n\n4. Верхняя точка\nЗадержитесь на 1 секунду в контролируемом разгибании.\n\n5. Возврат\nВерните рукояти назад медленно, сохраняя натяжение в грудных мышцах.\n\nКлючевые моменты\nДержите плечи опущенными\nНе выталкивайте вес инерцией\nРаботайте в полной контролируемой амплитуде',

  [normalizeExerciseName('Close-Grip Bench Press')]:
    'Техника выполнения\n1. Позиция\nЛягте на скамью, возьмитесь за штангу хватом уже плеч.\n\n2. Исходное положение\nЛопатки сведены, стопы в опоре, локти ближе к корпусу.\n\n3. Опускание\nОпускайте штангу к нижней части груди под контролем.\n\n4. Жим\nВыжимайте штангу вверх, сохраняя акцент на работе трицепса.\n\n5. Возврат\nПовторяйте без рывков и потери положения лопаток.\n\nКлючевые моменты\nХват не должен быть слишком узким до боли в запястьях\nЛокти направлены ближе к корпусу\nКонтроль внизу обязателен',

  [normalizeExerciseName('Rope Pushdown')]:
    'Техника выполнения\n1. Позиция\nВстаньте у верхнего блока с канатной рукоятью, корпус слегка наклонён вперёд.\n\n2. Исходное положение\nЛокти прижаты к корпусу, предплечья согнуты, плечи опущены.\n\n3. Разгибание\nРазгибайте руки вниз и в стороны, разводя концы каната внизу.\n\n4. Нижняя точка\nПолностью сократите трицепс и удержите 1 секунду.\n\n5. Возврат\nПод контролем верните рукоять вверх, не двигая локти вперёд.\n\nКлючевые моменты\nЛокти фиксированы у корпуса\nНе раскачивайте корпус\nРазведение каната внизу усиливает пиковое сокращение',

  [normalizeExerciseName('Dumbbell Skull Crushers')]:
    'Техника выполнения\n1. Позиция\nЛягте на скамью, гантели удерживаются над грудью, ладони смотрят друг на друга.\n\n2. Исходное положение\nПлечи стабильны, локти направлены вверх.\n\n3. Опускание\nСгибайте локти и опускайте гантели к вискам/по бокам головы под контролем.\n\n4. Разгибание\nРазгибайте локти и возвращайте гантели в исходное положение.\n\n5. Возврат\nДержите темп ровным, без рывков и потери контроля локтей.\n\nКлючевые моменты\nПлечо почти неподвижно, работает локтевой сустав\nНе разводите локти сильно в стороны\nНе используйте слишком большой вес',

  [normalizeExerciseName('Cable Crunch')]:
    'Техника выполнения\n1. Позиция\nЗакрепите канат на верхнем блоке и встаньте на колени лицом к тренажёру.\n\n2. Исходное положение\nВозьмитесь за канат у висков, таз стабилен, спина нейтральна.\n\n3. Скручивание\nСкручивайте корпус вниз, подводя рёбра к тазу за счёт мышц пресса.\n\n4. Нижняя точка\nСделайте короткую паузу в пиковой точке сокращения.\n\n5. Возврат\nМедленно вернитесь в исходное положение, не теряя напряжение пресса.\n\nКлючевые моменты\nНе тяните канат руками\nДвижение идёт через сгибание корпуса, а не тазом\nКонтроль в негативной фазе обязателен',

  [normalizeExerciseName('Hanging Knee Raises')]:
    'Техника выполнения\n1. Позиция\nПовисните на перекладине или упорах для пресса, корпус стабилен.\n\n2. Исходное положение\nНоги выпрямлены вниз, плечи опущены, пресс в лёгком напряжении.\n\n3. Подъём\nПодтягивайте колени к груди за счёт мышц пресса.\n\n4. Верхняя точка\nКоротко задержитесь, контролируя положение таза.\n\n5. Опускание\nПлавно опускайте ноги вниз без раскачки корпуса.\n\nКлючевые моменты\nНе используйте мах\nДержите лопатки активными и плечи опущенными\nКонтролируйте эксцентрическую фазу',

  [normalizeExerciseName('Hanging Leg Raises')]:
    'Техника выполнения\n1. Позиция\nПовисните на перекладине, руки на ширине плеч, корпус стабилен.\n\n2. Исходное положение\nНоги вместе и выпрямлены, плечи опущены, пресс напряжён.\n\n3. Подъём\nПоднимайте прямые ноги вперёд до уровня, который можете контролировать.\n\n4. Верхняя точка\nЗадержитесь на короткую паузу без раскачки.\n\n5. Опускание\nМедленно опустите ноги вниз, сохраняя контроль корпуса.\n\nКлючевые моменты\nНе раскачивайте таз и ноги\nЕсли тяжело, уменьшите амплитуду или согните ноги\nФокус на напряжении пресса, не на скорости',

  [normalizeExerciseName('Cable Biceps Curl')]:
    'Техника выполнения\n1. Позиция\nВстаньте к нижнему блоку, возьмите прямую или EZ-рукоять обратным хватом.\n\n2. Исходное положение\nРуки выпрямлены, локти у корпуса, плечи опущены.\n\n3. Сгибание\nПоднимайте рукоять вверх за счёт сгибания локтей, не двигая плечами.\n\n4. Верхняя точка\nСожмите бицепс и удержите 1 секунду.\n\n5. Возврат\nПлавно опустите рукоять в исходное положение, сохраняя натяжение троса.\n\nКлючевые моменты\nНе отклоняйтесь корпусом назад\nЛокти остаются фиксированы\nКонтролируйте негативную фазу',

  [normalizeExerciseName('Hammer Curl')]:
    'Техника выполнения\n1. Позиция\nВстаньте ровно, гантели вдоль корпуса нейтральным хватом (ладони смотрят друг на друга).\n\n2. Исходное положение\nЛокти прижаты к корпусу, плечи опущены, корпус стабилен.\n\n3. Сгибание\nПоднимайте гантели вверх без разворота кистей, сохраняя локти на месте.\n\n4. Верхняя точка\nСделайте короткую паузу и напрягите бицепс и плечелучевую мышцу.\n\n5. Возврат\nПлавно опустите гантели до полного разгибания рук.\n\nКлючевые моменты\nНе раскачивайте корпус\nНе выдвигайте локти вперёд\nРаботайте в полной амплитуде под контролем',

  [normalizeExerciseName('Reverse Curl')]:
    'Техника выполнения\n1. Позиция\nВстаньте прямо, удерживая штангу или EZ-гриф прямым хватом сверху.\n\n2. Исходное положение\nРуки выпрямлены, локти у корпуса, запястья нейтральны.\n\n3. Сгибание\nПоднимайте вес вверх за счёт сгибания локтей, не двигая плечами.\n\n4. Верхняя точка\nКоротко зафиксируйте сокращение вверху.\n\n5. Возврат\nМедленно опустите вес вниз, сохраняя контроль.\n\nКлючевые моменты\nНе заламывайте запястья\nНе используйте раскачку корпусом\nДержите локти прижатыми к телу',

  [normalizeExerciseName('Barbell Biceps Curl')]:
    'Техника выполнения\n1. Встаньте прямо, штанга в руках обратным хватом.\n2. Локти прижаты к корпусу, корпус стабилен.\n3. Поднимайте штангу к плечам за счёт сгибания локтей.\n4. Вверху сделайте короткую паузу и сожмите бицепс.\n5. Медленно опустите штангу вниз под контролем.\n\nКлючевые моменты\nНе раскачивайте корпус\nНе выводите локти вперёд\nРаботайте в полной амплитуде',

  [normalizeExerciseName('Barbell Shrugs')]:
    'Техника выполнения\n1. Встаньте ровно, штанга у бёдер, хват на ширине плеч.\n2. Поднимайте плечи вверх строго вертикально.\n3. Задержитесь в верхней точке на 1 секунду.\n4. Плавно опустите плечи вниз под контролем.\n5. Повторяйте без круговых движений плечами.\n\nКлючевые моменты\nДвижение короткое и строго вертикальное\nНе тяните головой вперёд\nНе используйте рывки',

  [normalizeExerciseName('Bench Dips')]:
    'Техника выполнения\n1. Сядьте на край скамьи, ладони по бокам таза.\n2. Сместите таз вперёд, ноги выставьте перед собой.\n3. Сгибайте локти и опускайтесь до комфортной глубины.\n4. Разгибайте руки и возвращайтесь вверх.\n5. Держите темп ровным и подконтрольным.\n\nКлючевые моменты\nЛокти направлены назад\nНе опускайтесь через боль в плечах\nНе проваливайте грудной отдел',

  [normalizeExerciseName('Cable Chest Fly (Flat)')]:
    'Техника выполнения\n1. Встаньте между блоками, рукояти на уровне груди.\n2. Руки слегка согнуты, грудь раскрыта, корпус стабилен.\n3. Сводите руки по дуге перед собой.\n4. В пике сокращения удержите 1 секунду.\n5. Медленно разведите руки обратно, сохраняя натяжение тросов.\n\nКлючевые моменты\nУгол в локтях сохраняется\nНе сутультесь в конце движения\nКонтролируйте негативную фазу',

  [normalizeExerciseName('Cable Front Raise')]:
    'Техника выполнения\n1. Возьмитесь за нижний блок одной или двумя руками.\n2. Корпус стабилен, локти слегка согнуты.\n3. Поднимайте руки перед собой до уровня плеч.\n4. Коротко зафиксируйте верхнюю точку.\n5. Плавно опустите рукоять в исходное положение.\n\nКлючевые моменты\nНе поднимайте выше уровня плеч\nНе отклоняйтесь корпусом назад\nРаботайте без рывков',

  [normalizeExerciseName('Cable Kickback')]:
    'Техника выполнения\n1. Закрепите манжету на лодыжке и встаньте лицом к опоре.\n2. Опорная нога слегка согнута, корпус стабилен.\n3. Отводите рабочую ногу назад за счёт ягодицы.\n4. В крайней точке сожмите ягодицу и удержите 1 секунду.\n5. Верните ногу в старт без потери контроля.\n\nКлючевые моменты\nНе прогибайтесь в пояснице\nНе разворачивайте таз\nТемп ровный и подконтрольный',

  [normalizeExerciseName('Cable Kickbacks')]:
    'Техника выполнения\n1. Закрепите манжету на лодыжке и встаньте к блоку.\n2. Удерживайте корпус и таз неподвижными.\n3. Отводите ногу назад плавно, без инерции.\n4. В верхней точке зафиксируйте сокращение ягодицы.\n5. Медленно возвращайтесь в исходную позицию.\n\nКлючевые моменты\nРаботает ягодица, а не поясница\nНе ускоряйте возврат\nСохраняйте натяжение троса',

  [normalizeExerciseName('Cable Lateral Raise')]:
    'Техника выполнения\n1. Встаньте боком к нижнему блоку, рукоять в дальней руке.\n2. Рука слегка согнута в локте, плечо опущено.\n3. Поднимайте руку в сторону до уровня плеча.\n4. Коротко удержите верх и сожмите среднюю дельту.\n5. Медленно опустите руку вниз под контролем.\n\nКлючевые моменты\nНе поднимайте плечо к уху\nНе раскачивайте корпус\nКонтролируйте негатив',

  [normalizeExerciseName('Cable Overhead Extension')]:
    'Техника выполнения\n1. Встаньте к блоку спиной, канат за головой.\n2. Локти направлены вверх и близко к голове.\n3. Разгибайте руки вверх, сокращая трицепс.\n4. Вверху коротко зафиксируйте разгибание.\n5. Верните рукоять за голову под контролем.\n\nКлючевые моменты\nЛокти не разводите в стороны\nНе прогибайтесь в пояснице\nРаботайте в полной амплитуде',

  [normalizeExerciseName('Cable Shrugs')]:
    'Техника выполнения\n1. Возьмитесь за рукоять нижнего блока, корпус ровный.\n2. Поднимайте плечи строго вверх.\n3. В верхней точке задержитесь на 1 секунду.\n4. Медленно опустите плечи вниз.\n5. Повторяйте без круговых движений.\n\nКлючевые моменты\nНе крутите плечами\nНе используйте инерцию\nДержите шею нейтрально',

  [normalizeExerciseName('Cable Step-ups')]:
    'Техника выполнения\n1. Встаньте перед платформой, рукоять нижнего блока в руках.\n2. Поставьте рабочую стопу полностью на платформу.\n3. Поднимайтесь вверх через пятку опорной ноги.\n4. Полностью стабилизируйтесь в верхней точке.\n5. Плавно опуститесь вниз под контролем.\n\nКлючевые моменты\nНе помогайте задней ногой\nДержите колено по линии носка\nНе теряйте баланс корпуса',

  [normalizeExerciseName('Crunch')]:
    'Техника выполнения\n1. Лягте на спину, колени согнуты, стопы на полу.\n2. Поясница прижата, пресс напряжён.\n3. Поднимайте лопатки от пола короткой амплитудой.\n4. Вверху выдох и короткая пауза.\n5. Медленно вернитесь вниз без расслабления пресса.\n\nКлючевые моменты\nНе тяните шею руками\nНе бросайте корпус вниз\nДержите контроль во всех повторениях',

  [normalizeExerciseName('Curtsy Lunges with dumbbells')]:
    'Техника выполнения\n1. Встаньте прямо, гантели вдоль корпуса.\n2. Сделайте шаг назад по диагонали и опуститесь в выпад.\n3. Переднее колено направлено по линии стопы.\n4. Оттолкнитесь передней ногой и вернитесь в старт.\n5. Повторите на другую сторону.\n\nКлючевые моменты\nСохраняйте ровный корпус\nНе заваливайте колено внутрь\nРаботайте в контролируемой глубине',

  [normalizeExerciseName('Deadlift with dumbbell/barbell/Smith')]:
    'Техника выполнения\n1. Встаньте устойчиво, вес близко к ногам.\n2. Спина нейтральная, корпус напряжён, плечи опущены.\n3. Поднимайте вес за счёт разгибания коленей и таза.\n4. Вверху полностью выпрямитесь без переразгибания.\n5. Опустите вес вниз под контролем по той же траектории.\n\nКлючевые моменты\nДержите вес близко к корпусу\nНе округляйте поясницу\nНе рвите старт рывком',

  [normalizeExerciseName('Dips (Chest Focus)')]:
    'Техника выполнения\n1. Возьмитесь за брусья и поднимитесь на прямые руки.\n2. Слегка наклоните корпус вперёд для акцента на грудь.\n3. Опускайтесь, сгибая локти до комфортной глубины.\n4. Выжимайте себя вверх до разгибания рук.\n5. Сохраняйте стабильный темп без раскачки.\n\nКлючевые моменты\nЛокти идут назад и в стороны умеренно\nНе проваливайтесь в плечах\nГлубина только под контроль',

  [normalizeExerciseName('Dumbbell Deadlift')]:
    'Техника выполнения\n1. Встаньте на ширине таза, гантели перед бедрами.\n2. Спина ровная, колени слегка согнуты.\n3. Опускайте гантели вдоль ног за счёт тазового сгибания.\n4. Поднимайтесь, выводя таз вперёд и сохраняя нейтраль спины.\n5. Завершайте повтор без переразгибания в пояснице.\n\nКлючевые моменты\nГантели держите близко к ногам\nНе округляйте спину\nТемп контролируемый',

  [normalizeExerciseName('Dumbbell Shrugs')]:
    'Техника выполнения\n1. Встаньте ровно, гантели вдоль корпуса.\n2. Поднимайте плечи строго вверх.\n3. В верхней точке сделайте короткую паузу.\n4. Медленно опустите плечи вниз.\n5. Повторяйте без круговых движений.\n\nКлючевые моменты\nНе крутите плечами\nНе сгибайте шею\nНе используйте инерцию',

  [normalizeExerciseName('EZ-Bar Curl')]:
    'Техника выполнения\n1. Встаньте прямо, возьмите EZ-гриф снизу.\n2. Локти у корпуса, плечи опущены.\n3. Поднимайте гриф к плечам за счёт бицепса.\n4. Вверху задержитесь на 1 секунду.\n5. Опустите гриф медленно до полного разгибания.\n\nКлючевые моменты\nЛокти не выводите вперёд\nНе раскачивайтесь\nЗапястья держите нейтрально',

  [normalizeExerciseName('Front Raise (DB/Plate/Barbell)')]:
    'Техника выполнения\n1. Встаньте стабильно, отягощение перед бедрами.\n2. Локти слегка согнуты, корпус собран.\n3. Поднимайте руки перед собой до уровня плеч.\n4. Коротко фиксируйте верхнюю точку.\n5. Плавно опускайте вес вниз под контролем.\n\nКлючевые моменты\nНе поднимайте выше плеч\nНе отклоняйтесь назад\nКонтролируйте опускание',

  [normalizeExerciseName('Goblet Squat with dumbbell')]:
    'Техника выполнения\n1. Держите гантель у груди, стопы на ширине плеч.\n2. Отведите таз назад и опуститесь в присед.\n3. Колени направлены по линии носков.\n4. Поднимайтесь через пятки и середину стопы.\n5. Вверху стабилизируйте корпус и дыхание.\n\nКлючевые моменты\nНе заваливайте колени внутрь\nСохраняйте нейтральную спину\nРаботайте в комфортной глубине',

  [normalizeExerciseName('Horizontal Leg Press')]:
    'Техника выполнения\n1. Сядьте в тренажёр, спина прижата к опоре.\n2. Стопы на платформе на ширине плеч.\n3. Опускайте платформу до комфортной глубины.\n4. Выжимайте платформу вверх через пятки.\n5. Не блокируйте колени в верхней точке.\n\nКлючевые моменты\nПоясница не отрывается от спинки\nКолени направлены по носкам\nНе бросайте платформу вниз',

  [normalizeExerciseName('Vertical Leg Press')]:
    'Задействованные мышцы\n\nКвадрицепсы, ягодицы, задняя поверхность бедра\n\nТехника выполнения\n1. Позиция\n\nЛягте в вертикальный тренажёр, расположив спину и таз на опоре. Стопы поставьте на платформу на ширине плеч.\n\n2. Исходное положение\n\nСнимите блокировку. Ноги согнуты, платформа находится над вами. Поясница прижата к опоре.\n\n3. Движение\n\nРазгибайте ноги, выжимая платформу вверх. Давление через пятки и середину стопы.\n\n4. Верхняя точка\n\nПочти полностью выпрямите ноги, не блокируя колени.\n\n5. Возврат\n\nМедленно сгибайте ноги, опуская платформу вниз до комфортной глубины (примерно 90° в коленях).\n\n6. Дыхание\n\nВыдох при выжимании, вдох при опускании.\n\nКлючевые моменты\nПоясница остаётся прижатой к опоре на протяжении всего движения\nНе блокируйте колени в верхней точке\nКонтролируйте глубину, чтобы не терять положение таза\nПоложение стоп влияет на нагрузку: выше — больше ягодицы, ниже — больше квадрицепсы 💪',

  [normalizeExerciseName('Incline Dumbbell Curl')]:
    'Техника выполнения\n1. Сядьте на наклонную скамью с гантелями в руках.\n2. Руки свисают вниз, локти направлены к полу.\n3. Поднимайте гантели к плечам без движения локтей вперёд.\n4. Сожмите бицепс в верхней точке.\n5. Опустите гантели медленно до полного растяжения.\n\nКлючевые моменты\nНе раскачивайте корпус\nКонтролируйте нижнюю фазу\nНе сокращайте амплитуду',

  [normalizeExerciseName('Inverted Rows')]:
    'Техника выполнения\n1. Расположитесь под перекладиной, тело в прямой линии.\n2. Возьмитесь за перекладину хватом чуть шире плеч.\n3. Тяните грудь к перекладине, уводя локти назад.\n4. Вверху сведите лопатки и удержите паузу.\n5. Медленно выпрямите руки и вернитесь вниз.\n\nКлючевые моменты\nНе провисайте в тазу\nДержите корпус жёстким\nНе тяните только руками',

  [normalizeExerciseName('Kickbacks (Dumbbell)')]:
    'Техника выполнения\n1. Наклонитесь, зафиксируйте плечо у корпуса.\n2. Локоть согнут под 90 градусов.\n3. Разгибайте руку назад до полного сокращения трицепса.\n4. Коротко удержите верхнюю точку.\n5. Верните предплечье в старт под контролем.\n\nКлючевые моменты\nПлечо остаётся неподвижным\nБез рывков корпусом\nКонтролируйте возврат',

  [normalizeExerciseName('Lateral Raise (Dumbbell)')]:
    'Техника выполнения\n1. Встаньте ровно, гантели по бокам.\n2. Локти слегка согнуты, плечи опущены.\n3. Поднимайте руки в стороны до уровня плеч.\n4. Задержитесь на 1 секунду вверху.\n5. Медленно опустите гантели вниз.\n\nКлючевые моменты\nНе поднимайте руки выше плеч\nНе раскачивайте корпус\nВедите движение локтями',

  [normalizeExerciseName('Leg Curl')]:
    'Техника выполнения\n1. Настройте тренажёр сгибания ног под свой рост.\n2. Зафиксируйте корпус и положение валика.\n3. Сгибайте ноги, подтягивая валик к себе.\n4. Сожмите бицепс бедра в верхней точке.\n5. Медленно верните ноги в исходное положение.\n\nКлючевые моменты\nНе отрывайте таз от опоры\nНе бросайте вес вниз\nСохраняйте полный контроль',

  [normalizeExerciseName('Leg Curl Lying')]:
    'Техника выполнения\n1. Лягте в тренажёр, валик выше лодыжек.\n2. Корпус прижат, руки на рукоятях.\n3. Сгибайте ноги, подтягивая пятки к ягодицам.\n4. Вверху сделайте короткую паузу.\n5. Медленно разогните ноги обратно.\n\nКлючевые моменты\nТаз не отрывается от скамьи\nИзбегайте рывков\nКонтролируйте темп',

  [normalizeExerciseName('Leg Curl Sitting')]:
    'Техника выполнения\n1. Сядьте в тренажёр, отрегулируйте спинку и валики.\n2. Корпус прижат к спинке, ноги выпрямлены в старте.\n3. Сгибайте ноги в коленях под контролем.\n4. В верхней точке сожмите заднюю поверхность бедра.\n5. Плавно вернитесь в исходное положение.\n\nКлючевые моменты\nНе разгружайте вес внизу\nНе отрывайте таз\nДвижение без рывков',

  [normalizeExerciseName('Leg Extension Machine')]:
    'Техника выполнения\n1. Сядьте в тренажёр разгибания ног и настройте валик.\n2. Спина прижата, колени совпадают с осью тренажёра.\n3. Разгибайте ноги до почти полного выпрямления.\n4. Коротко зафиксируйте верхнюю точку.\n5. Медленно опустите ноги вниз под контролем.\n\nКлючевые моменты\nНе бросайте вес внизу\nНе разгибайте колено рывком\nКонтролируйте каждое повторение',

  [normalizeExerciseName('Lunges')]:
    'Техника выполнения\n1. Встаньте прямо, стопы на ширине таза.\n2. Сделайте шаг вперёд или назад и опуститесь в выпад.\n3. Обе ноги согнуты примерно до 90 градусов.\n4. Оттолкнитесь передней ногой и вернитесь в старт.\n5. Повторите на другую ногу.\n\nКлючевые моменты\nКорпус держите вертикально\nКолено идёт по линии носка\nШаг достаточно длинный для безопасной механики',

  [normalizeExerciseName('Machine Crunch')]:
    'Техника выполнения\n1. Сядьте в тренажёр, зафиксируйте таз и положение рук.\n2. Исходно спина нейтральна, пресс в лёгком напряжении.\n3. Скручивайте корпус вперёд за счёт мышц пресса.\n4. В нижней точке коротко удержите сокращение.\n5. Медленно вернитесь в старт без расслабления пресса.\n\nКлючевые моменты\nНе тяните движение руками\nНе бросайте вес обратно\nРаботайте в контролируемой амплитуде',

  [normalizeExerciseName('Machine Triceps Extension')]:
    'Техника выполнения\n1. Сядьте в тренажёр, локти зафиксируйте в опоре.\n2. В старте локти согнуты, корпус стабилен.\n3. Разгибайте руки до полного сокращения трицепса.\n4. Коротко зафиксируйте нижнюю точку.\n5. Медленно вернитесь в исходное положение.\n\nКлючевые моменты\nЛокти не отрывайте от опоры\nНе помогайте корпусом\nСохраняйте плавный темп',

  [normalizeExerciseName('One-Arm Row')]:
    'Техника выполнения\n1. Упритесь одной рукой и коленом в скамью, второй рукой держите гантель.\n2. Спина ровная, плечо рабочей руки опущено.\n3. Тяните гантель к тазу, ведя локоть назад.\n4. Вверху сведите лопатку и задержитесь на 1 секунду.\n5. Медленно опустите гантель вниз.\n\nКлючевые моменты\nНе разворачивайте корпус\nНе тяните плечом к уху\nКонтролируйте негатив',

  [normalizeExerciseName('Overhead Triceps Extension (DB)')]:
    'Техника выполнения\n1. Держите гантель двумя руками над головой.\n2. Локти направлены вверх и близко к голове.\n3. Опускайте гантель за голову, сгибая локти.\n4. Разгибайте руки вверх, сокращая трицепс.\n5. Повторяйте в плавном темпе без рывков.\n\nКлючевые моменты\nЛокти не разводите\nНе прогибайтесь в пояснице\nДержите контроль внизу',

  [normalizeExerciseName('Rear Delt Cable Fly')]:
    'Техника выполнения\n1. Встаньте между блоками и возьмитесь за рукояти крест-накрест.\n2. Локти слегка согнуты, корпус стабилен.\n3. Разводите руки в стороны до линии плеч.\n4. Вверху сведите лопатки и удержите паузу.\n5. Плавно верните руки в исходное положение.\n\nКлючевые моменты\nНе поднимайте плечи к ушам\nНе используйте инерцию\nФокус на задней дельте',

  [normalizeExerciseName('Rear Delt Dumbbell Fly')]:
    'Техника выполнения\n1. Наклоните корпус вперёд с ровной спиной, гантели внизу.\n2. Локти слегка согнуты, шея нейтральна.\n3. Разводите гантели в стороны до уровня плеч.\n4. Коротко зафиксируйте верхнюю точку.\n5. Медленно опустите гантели вниз.\n\nКлючевые моменты\nНе сводите лопатки чрезмерно\nНе раскачивайте корпус\nКонтроль важнее веса',

  [normalizeExerciseName('Reverse Crunch')]:
    'Техника выполнения\n1. Лягте на спину, колени согнуты, руки вдоль корпуса.\n2. Поясница прижата к полу.\n3. Подкрутите таз и подтяните колени к груди.\n4. В верхней точке сожмите нижний пресс.\n5. Плавно вернитесь в исходное положение.\n\nКлючевые моменты\nНе делайте мах ногами\nДвижение за счёт таза\nКонтролируйте опускание',

  [normalizeExerciseName('Reverse Pec Deck')]:
    'Техника выполнения\n1. Сядьте в тренажёр обратных разведений, грудь в опоре.\n2. Возьмитесь за рукояти нейтральным хватом.\n3. Разводите руки назад до линии плеч.\n4. В пике сведите лопатки и удержите 1 секунду.\n5. Медленно верните рукояти в старт.\n\nКлючевые моменты\nНе поднимайте плечи\nНе разгибайте поясницу\nКонтролируйте отрицательную фазу',

  [normalizeExerciseName('Romanian Deadlift with dumbbell/barbell')]:
    'Техника выполнения\n1. Встаньте ровно, вес держите перед бедрами.\n2. Колени слегка согнуты и фиксированы.\n3. Отводите таз назад, опуская вес вдоль ног.\n4. Поднимайтесь за счёт разгибания в тазобедренном суставе.\n5. Вверху сожмите ягодицы без переразгибания поясницы.\n\nКлючевые моменты\nСпина нейтральна всю амплитуду\nВес близко к ногам\nНе превращайте движение в присед',

  [normalizeExerciseName('Seated Calf Raises (machine)')]:
    'Техника выполнения\n1. Сядьте в тренажёр, подушки над коленями, носки на платформе.\n2. Опустите пятки вниз до растяжения икр.\n3. Поднимитесь на носки максимально вверх.\n4. В верхней точке удержите 1 секунду.\n5. Медленно опустите пятки обратно.\n\nКлючевые моменты\nРаботайте полной амплитудой\nНе подпрыгивайте\nКонтролируйте темп',

  [normalizeExerciseName('Seated Dumbbell Press')]:
    'Техника выполнения\n1. Сядьте на скамью со спинкой, гантели на уровне плеч.\n2. Спина прижата, корпус стабилен.\n3. Выжимайте гантели вверх до почти полного разгибания.\n4. Коротко зафиксируйте верхнюю точку.\n5. Опускайте гантели обратно под контролем.\n\nКлючевые моменты\nНе переразгибайте поясницу\nНе сталкивайте гантели сверху\nДержите запястья нейтрально',

  [normalizeExerciseName('Seated Machine Row (Hammer Strength)')]:
    'Техника выполнения\n1. Сядьте в тренажёр и зафиксируйте грудь в опоре.\n2. Возьмитесь за рукояти, плечи опущены.\n3. Тяните рукояти к корпусу, уводя локти назад.\n4. Сведите лопатки и удержите паузу.\n5. Медленно верните рукояти вперёд.\n\nКлючевые моменты\nНе тяните корпусом\nСохраняйте контакт с опорой\nКонтролируйте амплитуду',

  [normalizeExerciseName('Side Plank')]:
    'Техника выполнения\n1. Лягте на бок и упритесь на предплечье.\n2. Поднимите таз, выстроив тело в прямую линию.\n3. Удерживайте положение, напрягая пресс и ягодицы.\n4. Не допускайте провала таза вниз.\n5. Выполните на обе стороны.\n\nКлючевые моменты\nШея нейтральна\nКорпус не разворачивается\nДыхание ровное',

  [normalizeExerciseName('Single-Arm Pushdown')]:
    'Техника выполнения\n1. Возьмитесь одной рукой за рукоять верхнего блока.\n2. Локоть прижат к корпусу, плечо стабильно.\n3. Разгибайте руку вниз до полного сокращения трицепса.\n4. Внизу коротко удержите паузу.\n5. Медленно верните рукоять вверх и смените руку.\n\nКлючевые моменты\nНе уводите локоть вперёд\nНе помогайте корпусом\nКонтролируйте возврат',

  [normalizeExerciseName('Single-leg Calf Raises with dumbbell')]:
    'Техника выполнения\n1. Встаньте на платформу одной ногой, в другой руке гантель.\n2. Пятка свисает вниз для полной амплитуды.\n3. Поднимитесь на носок максимально высоко.\n4. Задержитесь вверху на 1 секунду.\n5. Медленно опустите пятку вниз под контролем.\n\nКлючевые моменты\nНе раскачивайтесь корпусом\nДержите баланс через опору при необходимости\nРаботайте медленно',

  [normalizeExerciseName('Single-Leg Leg Extension')]:
    'Техника выполнения\n1. Сядьте в тренажёр разгибания ног и настройте валик.\n2. Работайте одной ногой, вторая стабилизирует позицию.\n3. Разогните рабочую ногу до почти полного выпрямления.\n4. Вверху сделайте короткую паузу.\n5. Медленно опустите ногу и смените сторону.\n\nКлючевые моменты\nНе дёргайте вес\nКонтролируйте коленный сустав\nСоблюдайте одинаковую амплитуду на обе ноги',

  [normalizeExerciseName('Smith Machine Deadlift')]:
    'Техника выполнения\n1. Встаньте в Смите, гриф у середины стопы.\n2. Возьмитесь за гриф, спина нейтральна, корпус напряжён.\n3. Поднимайте гриф, разгибая колени и таз.\n4. Вверху выпрямитесь без переразгибания поясницы.\n5. Опустите гриф вниз по направляющим под контролем.\n\nКлючевые моменты\nДержите гриф близко к ногам\nНе округляйте спину\nНе стартуйте рывком',

  [normalizeExerciseName('Standing Cable Kickback')]:
    'Техника выполнения\n1. Закрепите манжету на лодыжке и встаньте лицом к опоре.\n2. Корпус стабилен, опорная нога слегка согнута.\n3. Отводите рабочую ногу назад за счёт ягодицы.\n4. В пике движения удержите сокращение 1 секунду.\n5. Верните ногу вперёд под контролем.\n\nКлючевые моменты\nНе разворачивайте таз\nНе прогибайтесь в пояснице\nКонтролируйте обратную фазу',

  [normalizeExerciseName('Standing Calf Raises (machine / dumbbell)')]:
    'Техника выполнения\n1. Встаньте на платформу тренажёра или на ступеньку с гантелью.\n2. Опустите пятки вниз до растяжения икр.\n3. Поднимитесь на носки максимально вверх.\n4. Сделайте короткую паузу в верхней точке.\n5. Медленно опуститесь вниз под контролем.\n\nКлючевые моменты\nНе подпрыгивайте\nДвигайтесь полной амплитудой\nТемп ровный и подконтрольный',

  [normalizeExerciseName('Stiff-Leg Deadlift')]:
    'Техника выполнения\n1. Встаньте с весом перед бедрами, ноги почти прямые.\n2. Колени слегка согнуты и фиксированы.\n3. Отводите таз назад и опускайте вес вдоль ног.\n4. Поднимайтесь вверх, сжимая ягодицы.\n5. Держите спину нейтральной на всей амплитуде.\n\nКлючевые моменты\nДвижение из тазобедренного сустава\nНе округляйте спину\nНе тяните вес рывком',

  [normalizeExerciseName('Straight-arm Pulldown (rope)')]:
    'Техника выполнения\n1. Встаньте к верхнему блоку с канатной рукоятью.\n2. Руки почти прямые, корпус слегка наклонён вперёд.\n3. Тяните канат вниз к бёдрам по дуге.\n4. Внизу сожмите широчайшие мышцы и удержите паузу.\n5. Верните рукоять вверх медленно под контролем.\n\nКлючевые моменты\nЛокти почти фиксированы\nНе превращайте движение в трицепс-разгибание\nБез раскачки корпусом',

  [normalizeExerciseName('Sumo Deadlift')]:
    'Техника выполнения\n1. Поставьте ноги широко, носки развернуты наружу.\n2. Возьмитесь за гриф между ног, спина нейтральна.\n3. Поднимайте штангу, разгибая колени и таз одновременно.\n4. Вверху выпрямитесь без переразгибания поясницы.\n5. Опустите штангу вниз по контролируемой траектории.\n\nКлючевые моменты\nКолени движутся по линии носков\nГриф держите близко к корпусу\nНе округляйте спину',

  [normalizeExerciseName('Sumo Squat with dumbbell / barbell / Smith machine')]:
    'Техника выполнения\n1. Встаньте в широкую стойку, носки развернуты наружу.\n2. Удерживайте отягощение перед корпусом.\n3. Опускайтесь в присед, направляя колени по линии носков.\n4. Поднимайтесь через пятки и середину стопы.\n5. В верхней точке сожмите ягодицы и стабилизируйте корпус.\n\nКлючевые моменты\nСохраняйте спину нейтральной\nНе сводите колени внутрь\nКонтролируйте глубину',

  [normalizeExerciseName('Superman Raises')]:
    'Техника выполнения\n1. Лягте на живот, руки вытянуты вперёд.\n2. Поднимайте руки, грудь и ноги одновременно.\n3. В верхней точке сожмите ягодицы и разгибатели спины.\n4. Сделайте короткую паузу без рывка.\n5. Плавно опуститесь в исходное положение.\n\nКлючевые моменты\nНе запрокидывайте голову\nДвижение контролируемое\nНе переразгибайте поясницу',

  [normalizeExerciseName('Underhand Lat Pulldown')]:
    'Техника выполнения\n1. Сядьте в тренажёр, возьмитесь за гриф обратным хватом.\n2. Грудь раскрыта, плечи опущены, корпус стабилен.\n3. Тяните гриф к верхней части груди, уводя локти вниз.\n4. В нижней точке сожмите широчайшие и удержите 1 секунду.\n5. Медленно верните гриф вверх до полного растяжения.\n\nКлючевые моменты\nНе раскачивайте корпус\nНе тяните плечи к ушам\nКонтролируйте возврат',

  [normalizeExerciseName('Woodchopper / Rotation Cable')]:
    'Техника выполнения\n1. Установите рукоять блока на уровне плеч или выше.\n2. Встаньте боком к тренажёру, корпус и таз стабильны.\n3. Выполняйте диагональный поворот вниз через мышцы кора.\n4. В нижней точке коротко зафиксируйте сокращение.\n5. Под контролем вернитесь в старт и повторите на обе стороны.\n\nКлючевые моменты\nДвижение идёт через корпус, не только руками\nНе сгибайте поясницу\nСохраняйте равновесие и темп',

  [normalizeExerciseName('Y-Raises (Incline or Standing)')]:
    'Техника выполнения\n1. Встаньте в наклон или лягте грудью на наклонную скамью.\n2. Руки опущены, большие пальцы направлены вверх.\n3. Поднимайте руки по траектории буквы Y.\n4. Вверху коротко удержите положение.\n5. Плавно опустите руки вниз под контролем.\n\nКлючевые моменты\nНе поднимайте плечи к ушам\nРаботайте небольшим весом\nКонтролируйте амплитуду без рывков',
}
